insert into english.sources(id, version, title, url, author, rights_note, modality, body, source_hash)
select r->>'id', (r->>'version')::int, r->>'title', r->>'url', r->>'author', r->>'rights_note', r->>'modality', r->>'body', r->>'source_hash'
from jsonb_array_elements($j$[{"id":"B-W1-HOMEWORK-S1","version":1,"title":"Short Blocks, Long Results (exam-style reading)","url":null,"author":"Pilot Kit B author","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"¶1 Many students sit down to do their homework with good intentions and stand up three hours later wondering where the time went. One reason is that the brain finds it hard to stay focused on a single task for a long period. Phones, snacks and conversations offer easy escapes, and every interruption makes it harder to return to the work.\n\n¶2 A simple method that many students find useful is to divide study time into short blocks. In each block, you work on one task for about twenty-five minutes, with your phone in another room. Then you take a five-minute break to stretch, drink some water or look out of the window. After four blocks, you take a longer rest.\n\n¶3 The method works for several reasons. First, a short block feels manageable, so it is easier to start. Second, because you know a break is coming, you are less tempted to stop in the middle. Third, counting the blocks gives you a realistic picture of how long a task really takes, which helps you plan the next day.\n\n¶4 However, the method is not magic. Some tasks, such as writing an essay, need longer periods of deep concentration, and a timer that rings in the middle of a good idea can be annoying. Students who use the method successfully tend to adapt it: they make the blocks longer for creative work and keep them short for tasks they find boring, such as memorising vocabulary.\n\n¶5 The most important lesson may be that how you study matters as much as how long you study. Two focused hours can achieve more than four distracted ones.","source_hash":"2a97c8ce345f1af4d1874f9c72f2bb329c18cd62444906a761e884dd6aeac65e"},{"id":"B-W1-HOMEWORK-S2","version":1,"title":"Homework policy (cloze)","url":null,"author":"Pilot Kit B author","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"Teachers at a secondary school decided to (1) ______ a new homework policy after many parents complained that their children were going to bed too late. Under the new rules, students in grade 9 receive no more than ninety minutes of homework a night, and teachers from different subjects must (2) ______ their plans so that big projects do not all arrive in the same week. The school also asked students to keep a record (3) ______ how long each task took. The results were (4) ______: some tasks that teachers expected to take twenty minutes were taking almost an hour. Teachers used this (5) ______ to shorten several assignments. Not everyone was happy at first. Some parents felt that less homework would make their children less (6) ______ for the entrance exam. However, after one term, most families agreed that the change had been (7) ______, especially for students who also attended extra classes. The school now plans to review the policy every year (8) ______ the help of a student committee.","source_hash":"868f012d91d0e03de5ad6194edd1ccf2f33bf29f5af685bc652f147c9545ebff"},{"id":"B-W1-HOMEWORK-S3","version":1,"title":"Source A — We Are Running Out of Evening","url":null,"author":"Imagined grade-9 student, school magazine, October 2026 (invented)","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"¶1 Last week I kept a diary of my evenings. On Monday I had homework in five subjects, and I finished at 11:40 p.m. On Wednesday it was 11:15. My friends say their weeks look the same. In a quick poll I ran in our class, 27 of 35 students said they regularly do more than three hours of homework a night.\n\n¶2 This is not sustainable. Teenagers need time to sleep, to exercise and simply to talk to their families. When every evening is filled with worksheets, we stop learning and start copying, just to get the work done.\n\n¶3 I am not asking for homework to be abolished. Some practice is useful, especially before tests. But each teacher sets work as if their subject were the only one. A limit of ninety minutes a night, shared fairly between subjects, would force teachers to choose the tasks that really matter. Quality, not quantity, should be the rule.","source_hash":"99badfe77e104907ef7a7f02c778213d5fef1d6f1fc3da7e0e3b1be50555114d"},{"id":"B-W1-HOMEWORK-S4","version":1,"title":"Source B — Homework Is Not the Enemy","url":null,"author":"Imagined secondary-school maths teacher, teachers' forum, October 2026 (invented)","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào. Nguồn dùng cho bài nói Chủ nhật: thầy/cô KHÔNG đọc trước.","modality":"text","body":"¶1 Every year, some students tell me they have too much homework. I take that seriously. But a strict time limit is the wrong answer.\n\n¶2 First, students work at very different speeds. A task that takes one student twenty minutes can take another an hour. A fixed limit would punish the slower students, who often need the practice most.\n\n¶3 Second, homework is where much of the learning actually happens. In class, students watch me solve problems; at home, they find out whether they can do it alone. Last year, students in my two classes who completed at least 80 per cent of their homework scored, on average, 1.2 points higher in the end-of-year test than those who did not.\n\n¶4 Of course, that does not prove that homework caused the difference; the students who did their homework may simply have been more motivated. Still, I believe the real problem is badly designed homework, such as long, repetitive worksheets, not homework itself. Teachers should coordinate across subjects and set fewer but better tasks.","source_hash":"9d49fd82e767309e077bc9e098b480e612de0781dd28e8b50f9db80aa88e862e"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'B-W1-HOMEWORK' and it.version = 1 and it.published_at is not null)
on conflict (id, version) do nothing;

