from jsonb_array_elements($j$[{"id":"B-W1-HOMEWORK","version":1,"track_id":"B","title_vi":"Tuần 1 — Bài tập về nhà","big_question_en":"Should there be a nightly time limit on homework for grade-9 students?","big_question_vi":"Có nên giới hạn thời gian làm bài tập về nhà mỗi tối cho học sinh lớp 9 không?","week":1,"date_from":"2026-10-19","date_to":"2026-10-25","domain_bucket":"society","target_ids":["B-T1-EXAM-R","B-L2-CLOZE","B-L1-TRANSFORM-W","B-T1-ARG-R","B-T5-DATAOP","B-T7-ARGUE","B-T11-QUALIFY","B-L1-COMPLEX-W","B-L2-PRECISE","B-L4-EXPLAIN-S","B-A3-REVISE"],"steps":[{"step_no":1,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-T1-EXAM-R"],"prompt_en":"No dictionary. 12 minutes. For questions 3, 5 and 6, also write the paragraph number and the first few words of the supporting sentence.","time_min":12,"planned_date":"2026-10-19","items":[{"id":"W1-A1-1","kind":"mcq","stem":"What is the passage mainly about?","options":["why homework takes students too long","how to stop using a phone while studying","a way of studying in short, focused blocks, and its limits","why essays need long periods of concentration"],"target_id":"B-T1-EXAM-R"},{"id":"W1-A1-2","kind":"mcq","stem":"According to paragraph 2, what should you do after four blocks?","options":["take a longer rest","start a new subject","check your phone","stop for the day"],"target_id":"B-T1-EXAM-R"},{"id":"W1-A1-3","kind":"mcq","stem":"The word \"manageable\" in paragraph 3 is closest in meaning to ______. (Write ¶ + supporting sentence.)","options":["compulsory","boring","expensive","possible to deal with"],"target_id":"B-T1-EXAM-R"},{"id":"W1-A1-4","kind":"mcq","stem":"Which of the following is NOT given as a reason why the method works?","options":["A short block is easier to start.","Breaks help you remember vocabulary better.","Knowing a break is coming makes you less likely to stop.","Counting blocks shows how long tasks really take."],"target_id":"B-T1-EXAM-R"},{"id":"W1-A1-5","kind":"mcq","stem":"The phrase \"not magic\" in paragraph 4 suggests that the method ______. (Write ¶ + supporting sentence.)","options":["has limits and does not suit every task","was invented by a famous teacher","is difficult to learn","only works for boring tasks"],"target_id":"B-T1-EXAM-R"},{"id":"W1-A1-6","kind":"mcq","stem":"The writer would most probably agree that ______. (Write ¶ + supporting sentence.)","options":["students should always study in 25-minute blocks","the length of a study block should depend on the kind of task","long study sessions are always better than short ones","breaks are a waste of time"],"target_id":"B-T1-EXAM-R"}],"self_check_vi":[]},{"step_no":2,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-L2-CLOZE"],"prompt_en":"Read the passage and choose the best answer for each gap. 8 minutes. No dictionary.","time_min":8,"planned_date":"2026-10-19","items":[{"id":"W1-A2-1","kind":"gap","stem":"Gap (1)","options":["introduce","invent","produce","reduce"],"target_id":"B-L2-CLOZE"},{"id":"W1-A2-2","kind":"word_form","stem":"Gap (2)","options":["coordination","coordinate","coordinator","coordinated"],"target_id":"B-L2-CLOZE"},{"id":"W1-A2-3","kind":"gap","stem":"Gap (3)","options":["in","for","of","with"],"target_id":"B-L2-CLOZE"},{"id":"W1-A2-4","kind":"word_form","stem":"Gap (4)","options":["surprise","surprised","surprising","surprisingly"],"target_id":"B-L2-CLOZE"},{"id":"W1-A2-5","kind":"gap","stem":"Gap (5)","options":["opinion","rumour","excuse","information"],"target_id":"B-L2-CLOZE"},{"id":"W1-A2-6","kind":"gap","stem":"Gap (6)","options":["busy","ready","careful","tired"],"target_id":"B-L2-CLOZE"},{"id":"W1-A2-7","kind":"word_form","stem":"Gap (7)","options":["benefit","beneficiary","beneficially","beneficial"],"target_id":"B-L2-CLOZE"},{"id":"W1-A2-8","kind":"gap","stem":"Gap (8)","options":["with","by","under","from"],"target_id":"B-L2-CLOZE"}],"self_check_vi":[]},{"step_no":3,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["B-L1-TRANSFORM-W"],"prompt_en":"Rewrite each sentence so that it means the same as the first one. Use the words given.","time_min":10,"planned_date":"2026-10-20","items":[{"id":"W1-A3-1","kind":"transform","stem":"\"I finished my project last night,\" said Lan. → Lan said (that) ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W1-A3-2","kind":"transform","stem":"Our teacher marks the homework every Friday. → The homework ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W1-A3-3","kind":"transform","stem":"I don't have a quiet room, so I can't concentrate at home. → If I ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W1-A3-4","kind":"transform","stem":"I'm sorry I didn't start my essay earlier. → I wish ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W1-A3-5","kind":"transform","stem":"The task was so difficult that I couldn't finish it in an hour. → The task was too ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W1-A3-6","kind":"transform","stem":"Although she was tired, she finished all her exercises. → Despite ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W1-A3-7","kind":"transform","stem":"No student in my class works harder than Minh. → Minh ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W1-A3-8","kind":"transform","stem":"I usually spend two hours doing homework every evening. → It usually takes ……","options":[],"target_id":"B-L1-TRANSFORM-W"}],"self_check_vi":[]},{"step_no":4,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-T1-ARG-R","B-T5-DATAOP"],"prompt_en":"Read Sources A and B (10 minutes), then answer the questions (20 minutes).","time_min":30,"planned_date":"2026-10-21","items":[{"id":"W1-B1-1","kind":"short","stem":"In one sentence each, in your own words, what is the main claim of Source A and of Source B?","options":[],"target_id":"B-T1-ARG-R"},{"id":"W1-B1-2","kind":"short","stem":"List three reasons or pieces of evidence that the writer of Source A uses. Give the paragraph (¶).","options":[],"target_id":"B-T1-ARG-R"},{"id":"W1-B1-3a","kind":"mcq","stem":"The writer of Source A wants homework to be:","options":["abolished completely","limited and shared fairly between subjects","given only before tests","replaced by projects"],"target_id":"B-T1-ARG-R"},{"id":"W1-B1-3b","kind":"mcq","stem":"The writer of Source B thinks a strict time limit is:","options":["the best solution","unnecessary, because there is no problem","the wrong solution to a real problem","fair to slower students"],"target_id":"B-T1-ARG-R"},{"id":"W1-B1-4i","kind":"mcq","stem":"\"On Monday I had homework in five subjects, and I finished at 11:40 p.m.\" (A)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W1-B1-4ii","kind":"mcq","stem":"\"This is not sustainable.\" (A)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W1-B1-4iii","kind":"mcq","stem":"\"27 of 35 students said they regularly do more than three hours of homework a night.\" (A)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W1-B1-4iv","kind":"mcq","stem":"\"A fixed limit would punish the slower students.\" (B)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W1-B1-4v","kind":"mcq","stem":"\"When every evening is filled with worksheets, we stop learning and start copying.\" (A)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W1-B1-4vi","kind":"mcq","stem":"\"On Wednesday it was 11:15.\" (A)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W1-B1-4vii","kind":"mcq","stem":"\"Students… who completed at least 80 per cent of their homework scored, on average, 1.2 points higher in the end-of-year test.\" (B)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W1-B1-4viii","kind":"mcq","stem":"\"The real problem is badly designed homework… not homework itself.\" (B)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W1-B1-5","kind":"open","stem":"Choose two statements you marked C. For each, explain in 1-2 sentences why it is commentary, not data.","options":[],"target_id":"B-T5-DATAOP"}],"self_check_vi":[]},{"step_no":5,"activity_type":"ACT-CANVAS-ADV","mode":"PRACTICE","purpose":[],"target_ids":["B-T7-ARGUE","B-T11-QUALIFY"],"prompt_en":"Practice question: According to the two sources, is the main problem the amount of homework or the way it is set? 1. Fill in the Canvas (with sentence frames). 2. Write one paragraph of 80-120 words. Canvas boxes: Question · 1. Your answer (My answer is that …) · 2. Reasons + evidence, each with [Source, ¶] (One reason is that … Source B shows this: \"…\" (¶2).) · 3. Why the evidence supports the reason (This supports my point because …) · 4. Limitation (However, this evidence is limited because …) · 5. Conditional conclusion (So it is likely / possible that …, unless / as long as …)","time_min":20,"planned_date":"2026-10-22","items":[],"self_check_vi":[]},{"step_no":6,"activity_type":"ACT-SOURCE-QA","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Choose A, B, C or D. 10 minutes.","time_min":10,"planned_date":"2026-10-23","items":[{"id":"W1-Q-1","kind":"mcq","stem":"-ed: cook[ed] / play[ed] / watch[ed] / wash[ed]","options":["cooked","played","watched","washed"],"target_id":null},{"id":"W1-Q-2","kind":"mcq","stem":"Choose the sentence that is correctly made from these words: our teacher / ask / us / hand in / project / before Friday","options":["Our teacher asks us hand in the project before Friday.","Our teacher asked us handing in the project before Friday.","Our teacher asked us to hand in the project before Friday.","Our teacher asked that us hand in project before Friday."],"target_id":null},{"id":"W1-Q-3","kind":"mcq","stem":"Stress","options":["begin","teacher","careful","homework"],"target_id":null},{"id":"W1-Q-4","kind":"mcq","stem":"Stress","options":["education","activity","environment","experience"],"target_id":null},{"id":"W1-Q-5","kind":"mcq","stem":"By the time we arrived, the film ______.","options":["has started","starts","had started","was starting"],"target_id":null},{"id":"W1-Q-6","kind":"mcq","stem":"Choose the best order to make a short paragraph: a. First, I write down everything I have to do. b. I follow a simple routine when I do my homework. c. Finally, I check my answers before I close my books. d. Then I start with the hardest subject while I still feel fresh.","options":["a–b–d–c","d–b–a–c","b–d–a–c","b–a–d–c"],"target_id":null},{"id":"W1-Q-7","kind":"mcq","stem":"Tom: \"I've just won the school poetry prize!\" – Anna: \"______\"","options":["Never mind.","Same to you.","Help yourself.","Congratulations!"],"target_id":null},{"id":"W1-Q-8","kind":"mcq","stem":"Notice at the canteen exit: PLEASE RETURN TRAYS HERE. No food in the library.","options":["You can eat in the library if you return your tray.","Trays should be returned here, and you must not eat in the library.","The library sells food.","Trays are not allowed in the canteen."],"target_id":null}],"self_check_vi":[]},{"step_no":7,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-T7-ARGUE","B-T11-QUALIFY","B-L1-COMPLEX-W","B-L2-PRECISE"],"prompt_en":"Should there be a nightly time limit on homework for grade-9 students? Write 250-300 words. You may keep Sources A and B open. First, make a quick Canvas in 5 minutes (no frames): your answer, at least two reasons, each with [Source, ¶], one limitation, and your conclusion. State your position clearly. Use evidence from both sources. Explain how at least one piece of evidence supports your reason. Mention one limitation of the evidence. End with a conclusion that says how sure you are. No dictionary, no spell-check, no AI.","time_min":45,"planned_date":"2026-10-24","items":[],"self_check_vi":["Câu đầu tiên đã trả lời thẳng câu hỏi chưa?","Mỗi lý do đã có ít nhất một chỗ dẫn từ nguồn (Nguồn A hay B, đoạn mấy) chưa?","Có ít nhất một chỗ bạn giải thích vì sao bằng chứng ấy đỡ cho lý do của mình chưa?","Bạn đã nêu một giới hạn của bằng chứng chưa?","Kết luận đã nói rõ bạn chắc đến đâu (likely, in most cases…) và khi nào thì kết luận sẽ khác (unless…, if…) chưa?","Bài đã đủ 250 từ chưa? Có vài câu phức với which, who, although, if… chưa?","Đọc lại một lượt, chỉ để tìm 3 lỗi bạn hay mắc nhất.","Bạn có trả lời được lý do mạnh nhất của phía không giống ý mình không?"]},{"step_no":8,"activity_type":"ACT-REVISE","mode":"REVISION","purpose":[],"target_ids":["B-A3-REVISE"],"prompt_en":"Read the (max 3) comments. Fix only those places. Underline what you changed and add one line: \"I changed … because …\".","time_min":15,"planned_date":"2026-10-25","items":[],"self_check_vi":["Chỉ sửa những chỗ có gợi ý (tối đa 3), không viết lại cả bài.","Gạch chân chỗ đã sửa và ghi một dòng cuối: \"Mình đã sửa … vì …\"."]},{"step_no":9,"activity_type":"ACT-SPEAK-LIVE","mode":"PRACTICE","purpose":[],"target_ids":["B-L4-EXPLAIN-S"],"prompt_en":"Read Source B again for 2 minutes. You may write up to 5 key words on a card. Then explain the writer's argument to your teacher, who has not read it, in 2-3 minutes, so that they can say it back to you in one sentence. Give at least one example from your own life.","time_min":12,"planned_date":"2026-10-25","items":[],"self_check_vi":[]}],"sources":[{"id":"B-W1-HOMEWORK-S1","version":1,"title":"Short Blocks, Long Results (exam-style reading)","modality":"text","url":null},{"id":"B-W1-HOMEWORK-S2","version":1,"title":"Homework policy (cloze)","modality":"text","url":null},{"id":"B-W1-HOMEWORK-S3","version":1,"title":"Source A — We Are Running Out of Evening","modality":"text","url":null},{"id":"B-W1-HOMEWORK-S4","version":1,"title":"Source B — Homework Is Not the Enemy","modality":"text","url":null}]}]$j$::jsonb) as r
