insert into english.template_item_keys(template_id, template_version, item_id, step_no, kind, answer, explanation_vi)
select 'B-W1-HOMEWORK', 1, r->>'item_id', (r->>'step_no')::int, r->>'kind', r->>'answer', r->>'explanation_vi'
from jsonb_array_elements($j$[{"step_no":1,"item_id":"W1-A1-1","kind":"answer","answer":"C","explanation_vi":"Ý chính cả bài (cả phương pháp lẫn giới hạn ở ¶4)."},{"step_no":1,"item_id":"W1-A1-2","kind":"answer","answer":"A","explanation_vi":"¶2 \"After four blocks, you take a longer rest.\""},{"step_no":1,"item_id":"W1-A1-3","kind":"answer","answer":"D","explanation_vi":"¶3 \"a short block feels manageable, so it is easier to start\"."},{"step_no":1,"item_id":"W1-A1-4","kind":"answer","answer":"B","explanation_vi":"Bài không nói giờ nghỉ giúp nhớ từ vựng."},{"step_no":1,"item_id":"W1-A1-5","kind":"answer","answer":"A","explanation_vi":"¶4 \"Some tasks… need longer periods… annoying\"."},{"step_no":1,"item_id":"W1-A1-6","kind":"answer","answer":"B","explanation_vi":"¶4 \"make the blocks longer for creative work and keep them short for tasks they find boring\"."},{"step_no":1,"item_id":"step-1:note","kind":"note","answer":null,"explanation_vi":"Thứ Hai 19/10 · A1 đọc hiểu (270 từ). c1 ≥ 5/6; c2 dẫn đúng câu ≥ 2/3 (câu 3, 5, 6)."},{"step_no":2,"item_id":"W1-A2-1","kind":"answer","answer":"A","explanation_vi":"introduce a policy = ban hành, áp dụng chính sách."},{"step_no":2,"item_id":"W1-A2-2","kind":"answer","answer":"B","explanation_vi":"must + động từ nguyên mẫu."},{"step_no":2,"item_id":"W1-A2-3","kind":"answer","answer":"C","explanation_vi":"keep a record of."},{"step_no":2,"item_id":"W1-A2-4","kind":"answer","answer":"C","explanation_vi":"Kết quả gây ngạc nhiên → surprising."},{"step_no":2,"item_id":"W1-A2-5","kind":"answer","answer":"D","explanation_vi":"Dữ liệu ghi chép thời gian = information."},{"step_no":2,"item_id":"W1-A2-6","kind":"answer","answer":"B","explanation_vi":"ready for the entrance exam."},{"step_no":2,"item_id":"W1-A2-7","kind":"answer","answer":"D","explanation_vi":"had been + tính từ."},{"step_no":2,"item_id":"W1-A2-8","kind":"answer","answer":"A","explanation_vi":"with the help of."},{"step_no":2,"item_id":"step-2:note","kind":"note","answer":null,"explanation_vi":"Thứ Hai 19/10 · A2 điền đoạn văn (165 từ). c1 ≥ 6/8; c2 dạng từ (2, 4, 7) ≥ 2/3. Sau đó 5' ghi sổ lỗi."},{"step_no":3,"item_id":"W1-A3-1","kind":"answer","answer":"Lan said (that) she had finished her project the night before.","explanation_vi":"Cũng chấp nhận: …the previous night / the previous evening · Không chấp nhận: she finished (không lùi thì); giữ last night; yesterday"},{"step_no":3,"item_id":"W1-A3-2","kind":"answer","answer":"The homework is marked by our teacher every Friday.","explanation_vi":"Cũng chấp nhận: …is marked every Friday by our teacher · Không chấp nhận: was marked; is marking; bỏ by our teacher (tác nhân cụ thể phải giữ)"},{"step_no":3,"item_id":"W1-A3-3","kind":"answer","answer":"If I had a quiet room, I could concentrate at home.","explanation_vi":"Cũng chấp nhận: …I would be able to concentrate at home · Không chấp nhận: If I have…; If I had…, I can…"},{"step_no":3,"item_id":"W1-A3-4","kind":"answer","answer":"I wish I had started my essay earlier.","explanation_vi":"Cũng chấp nhận: I wish I'd started… · Không chấp nhận: I wish I started…; I wish I would start…"},{"step_no":3,"item_id":"W1-A3-5","kind":"answer","answer":"The task was too difficult for me to finish in an hour.","explanation_vi":"Cũng chấp nhận: …in one hour · Không chấp nhận: …to finish it… (lặp tân ngữ); bỏ for me"},{"step_no":3,"item_id":"W1-A3-6","kind":"answer","answer":"Despite being tired, she finished all her exercises.","explanation_vi":"Cũng chấp nhận: Despite her tiredness, … · Despite the fact that she was tired, … · Không chấp nhận: Despite she was tired; Despite of"},{"step_no":3,"item_id":"W1-A3-7","kind":"answer","answer":"Minh works the hardest in my class.","explanation_vi":"Cũng chấp nhận: Minh works harder than any other student in my class. · Minh is the hardest-working student in my class. · Minh works hardest in my class. · Không chấp nhận: …than any student… (thiếu other); the most hard"},{"step_no":3,"item_id":"W1-A3-8","kind":"answer","answer":"It usually takes me two hours to do my homework every evening.","explanation_vi":"Cũng chấp nhận: …to do homework… · …takes me two hours every evening to do my homework · Không chấp nhận: …takes me two hours doing…; …takes two hours for me doing…"},{"step_no":3,"item_id":"step-3:note","kind":"note","answer":null,"explanation_vi":"Thứ Ba 20/10, đầu buổi học, thầy/cô quan sát (observed_directly=Y, validator_role=tutor). c1 ≥ 7/8; c2 không sai ở cấu trúc cần dùng."},{"step_no":4,"item_id":"W1-B1-1","kind":"sealed","answer":"A: there should be a limit of about 90 minutes a night, shared fairly between subjects (not abolishing homework). B: a strict time limit is the wrong answer; the real problem is badly designed homework, so teachers should coordinate and set fewer, better tasks.","explanation_vi":"Cần đúng cả hai (c1 B-T1-ARG-R)."},{"step_no":4,"item_id":"W1-B1-2","kind":"sealed","answer":"3 trong: nhật ký 5 môn, xong lúc 11:40 / 11:15 (¶1) · khảo sát lớp 27/35 trên 3 giờ (¶1) · tuổi teen cần ngủ, tập thể dục, trò chuyện (¶2) · quá tải thì chép chứ không học (¶2) · mỗi giáo viên giao như thể chỉ có môn mình (¶3).","explanation_vi":"c2 B-T1-ARG-R."},{"step_no":4,"item_id":"W1-B1-3a","kind":"answer","answer":"B","explanation_vi":"Cần đúng cả 3a và 3b (c3 B-T1-ARG-R)."},{"step_no":4,"item_id":"W1-B1-3b","kind":"answer","answer":"C","explanation_vi":"Cần đúng cả 3a và 3b."},{"step_no":4,"item_id":"W1-B1-4i","kind":"answer","answer":"A","explanation_vi":"Dữ liệu/bằng chứng (D)."},{"step_no":4,"item_id":"W1-B1-4ii","kind":"answer","answer":"B","explanation_vi":"Bình luận/diễn giải (C)."},{"step_no":4,"item_id":"W1-B1-4iii","kind":"answer","answer":"A","explanation_vi":"Dữ liệu/bằng chứng (D)."},{"step_no":4,"item_id":"W1-B1-4iv","kind":"answer","answer":"B","explanation_vi":"Dự đoán, không phải điều đã đo."},{"step_no":4,"item_id":"W1-B1-4v","kind":"answer","answer":"B","explanation_vi":"Bình luận/diễn giải (C)."},{"step_no":4,"item_id":"W1-B1-4vi","kind":"answer","answer":"A","explanation_vi":"Dữ liệu/bằng chứng (D)."},{"step_no":4,"item_id":"W1-B1-4vii","kind":"answer","answer":"A","explanation_vi":"Dữ liệu/bằng chứng (D)."},{"step_no":4,"item_id":"W1-B1-4viii","kind":"answer","answer":"B","explanation_vi":"Bình luận/diễn giải (C)."},{"step_no":4,"item_id":"W1-B1-5","kind":"sealed","answer":"Ví dụ: (iv) dự đoán · (ii) đánh giá của người viết · (v) khái quát từ trải nghiệm · (viii) ý kiến về nguyên nhân.","explanation_vi":"c2 B-T5-DATAOP (c1 ≥ 7/8)."},{"step_no":4,"item_id":"step-4:note","kind":"note","answer":null,"explanation_vi":"Thứ Tư 21/10 · Câu hỏi về nguồn. Phụ huynh chấm."},{"step_no":5,"item_id":"step-5:note","kind":"note","answer":null,"explanation_vi":"Thứ Năm 22/10 · Bài luyện tập có câu mẫu (support_used=frame). Câu hỏi luyện tập khác câu hỏi lớn."},{"step_no":6,"item_id":"W1-Q-1","kind":"answer","answer":"B","explanation_vi":"played /d/, còn lại /t/."},{"step_no":6,"item_id":"W1-Q-2","kind":"answer","answer":"C","explanation_vi":"Dựng câu: ask + tân ngữ + to + động từ nguyên mẫu (asked us to hand in). A thiếu to; B dùng V-ing sau asked us; D dùng that-clause sai (that us)."},{"step_no":6,"item_id":"W1-Q-3","kind":"answer","answer":"A","explanation_vi":"begin nhấn âm 2."},{"step_no":6,"item_id":"W1-Q-4","kind":"answer","answer":"A","explanation_vi":"edu'cation nhấn âm 3, còn lại âm 2."},{"step_no":6,"item_id":"W1-Q-5","kind":"answer","answer":"C","explanation_vi":"Quá khứ hoàn thành."},{"step_no":6,"item_id":"W1-Q-6","kind":"answer","answer":"D","explanation_vi":"b (câu chủ đề) – a (First) – d (Then) – c (Finally)."},{"step_no":6,"item_id":"W1-Q-7","kind":"answer","answer":"D","explanation_vi":null},{"step_no":6,"item_id":"W1-Q-8","kind":"answer","answer":"B","explanation_vi":"(Đề xuất ⚪: đổi \"Canteen notice\" thành \"Notice at the canteen exit\".)"},{"step_no":6,"item_id":"step-6:note","kind":"note","answer":null,"explanation_vi":"Thứ Sáu 23/10 · Luyện nhanh 8 câu (không ghi CSV, chỉ ghi sổ lỗi)."},{"step_no":7,"item_id":"step-7:note","kind":"note","answer":null,"explanation_vi":"Thứ Bảy 24/10 · Canvas nhanh 5' + viết 35' + tự kiểm 5'. Nguồn để mở là điều kiện của bài (ghi support_note). B-L1-COMPLEX-W để trống nếu < 250 từ."},{"step_no":8,"item_id":"step-8:note","kind":"note","answer":null,"explanation_vi":"Chủ nhật 25/10 chiều · attempt_no=2, is_first_attempt=N, cùng learning_family FAM-B-HW-1."},{"step_no":9,"item_id":"step-9:note","kind":"note","answer":null,"explanation_vi":"Chủ nhật 25/10, trong buổi (≈ 12'). Bài luyện tập (support_used=notes), purpose=none. Ý chính (phụ huynh giữ, mở sau khi thầy/cô nhắc lại): \"A fixed homework time limit is the wrong fix, because students work at different speeds and homework is where they practise alone; the real problem is badly designed, uncoordinated homework, so teachers should set fewer, better tasks.\" Trao đổi 3' không chấm."}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'B-W1-HOMEWORK' and it.version = 1 and it.published_at is not null)
on conflict (template_id, template_version, item_id) do nothing;

update english.inquiry_templates set status = 'published', published_at = now()
where id = 'B-W1-HOMEWORK' and version = 1 and published_at is null;

-- Inquiry template B-W2-PHONES v1 (published after its sources and answer keys are in)
insert into english.sources(id, version, title, url, author, rights_note, modality, body, source_hash)
select r->>'id', (r->>'version')::int, r->>'title', r->>'url', r->>'author', r->>'rights_note', r->>'modality', r->>'body', r->>'source_hash'
from jsonb_array_elements($j$[{"id":"B-W2-PHONES-S1","version":1,"title":"A Week Without a Smartphone (exam-style reading)","url":null,"author":"Pilot Kit B author","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"¶1 When Linh's class teacher suggested a \"phone-free week\", most of the class laughed. Linh, who is fifteen, admits that she used to check her phone more than a hundred times a day, often without noticing. \"It was like a reflex,\" she says. \"I would pick it up just because it was there.\"\n\n¶2 The rules of the challenge were simple. Students could keep a basic phone for calls and messages to their families, but there would be no social media, games or videos for seven days. Anyone who gave up could rejoin the next day, with no punishment.\n\n¶3 The first two days were the hardest. Linh kept reaching into her pocket for a phone that was not there, and she felt anxious that she was missing important news from her friends. By Wednesday, however, something had changed. She noticed that she was finishing her homework earlier, and she had started reading a novel she had abandoned months before. \"I wasn't cleverer,\" she says. \"I just had fewer interruptions.\"\n\n¶4 Not every student had the same experience. Of the thirty-two who started, eleven gave up before the end of the week, and some said the challenge made them feel left out, because their friends in other classes were still chatting online without them.\n\n¶5 At the end of the week, the class discussed what they had learned. Few students wanted to give up their smartphones permanently. Instead, many decided to set their own rules, such as leaving the phone outside the bedroom at night. Linh's rule is simple: no phone until her homework is finished. \"I still love my phone,\" she says. \"I just don't want it to be the boss.\"","source_hash":"ed6d2c2fc6e994aeb290ff4273c18396dd841a10eac83a405e7d9b33ae7adfd9"},{"id":"B-W2-PHONES-S2","version":1,"title":"Phones and sleep (cloze)","url":null,"author":"Pilot Kit B author","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"Many teenagers take their phones to bed, and doctors are increasingly (1) ______ about the effect this has on sleep. There are two main problems. The first is simple: time spent scrolling is time not spent sleeping. The second is that messages and videos keep the brain (2) ______, which makes it harder to fall asleep (3) ______ the screen is switched off. Some families have found a (4) ______ solution: all phones are charged in the kitchen overnight. Parents who try this often say it works best when they follow the rule (5) ______, rather than only asking their children to do it. Teenagers, for their part, say they are more likely to accept a rule if they have been (6) ______ in making it. Experts also suggest using an ordinary alarm clock, so that there is no (7) ______ for the phone to be in the bedroom at all. Small changes like these can make a big (8) ______ to how rested students feel in the morning.","source_hash":"9b6c0089cd782c9d238109ee0b465f64e2242943c05639c146dfe845220326d5"},{"id":"B-W2-PHONES-S3","version":1,"title":"Source A — Phones Away, Heads Up","url":null,"author":"Imagined head teacher, school newsletter for parents, 28 September 2026 (invented)","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào. Nguồn dùng cho bài nói Chủ nhật: thầy/cô KHÔNG đọc trước.","modality":"text","body":"¶1 Four weeks ago, our school became phone-free. Students now hand in their phones at the gate in the morning and collect them at 4:30 p.m. I want to thank parents for supporting this important change.\n\n¶2 The results so far are encouraging. Break times are noisier and happier: students are finally playing football and table tennis again instead of staring silently at screens. Teachers tell me that lessons start faster because nobody is checking messages. Most importantly, reports of online bullying to our school counsellor fell from nine in the month before the ban to two in the first month after it.\n\n¶3 Some students have complained, and that is understandable. Change is never easy. But childhood should not be spent looking down at a screen, and I am confident that in a year's time no one will want to go back.","source_hash":"39b8fa86c454e74728fa5b1f3edf9aa90d6ee92a5bfaffeb1aedd5b7191851e9"},{"id":"B-W2-PHONES-S4","version":1,"title":"Source B — Ban the Misuse, Not the Phone","url":null,"author":"Imagined grade-11 student campaigner, student-run blog, 10 October 2026 (invented)","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"¶1 Every time a school bans phones, adults celebrate. But a full-day ban treats every student as someone who cannot control themselves, and it takes away a useful tool.\n\n¶2 Last week, we asked readers of this blog how they use their phones at school. Of the 80 students who replied, 64 said they use them for dictionaries, timetables or contacting their parents after clubs. Banning phones all day makes these simple things harder.\n\n¶3 It is also too early to say that bans stop bullying. Bullying does not disappear when phones are locked away at 7 a.m.; it can simply move to the evening, when teachers cannot see it.\n\n¶4 Schools should teach responsible use instead: phones away in lessons, allowed at break, and clear consequences for misuse. That is how we will learn to manage technology as adults.","source_hash":"84b9639be2bd9082a9ab2eae6528e712e287e5352f01eee38e0e16be8ea9cd8a"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'B-W2-PHONES' and it.version = 1 and it.published_at is not null)
on conflict (id, version) do nothing;

update english.sources set published_at = now()
where version = 1 and id in ('B-W2-PHONES-S1', 'B-W2-PHONES-S2', 'B-W2-PHONES-S3', 'B-W2-PHONES-S4') and published_at is null;

insert into english.inquiry_templates(id, version, track_id, title_vi, big_question_en, big_question_vi, week, date_from, date_to, domain_bucket, target_ids, steps, sources, catalogue_version, status, source_hash)
select r->>'id', (r->>'version')::int, r->>'track_id', r->>'title_vi', r->>'big_question_en', r->>'big_question_vi', (r->>'week')::int,
  (r->>'date_from')::date, (r->>'date_to')::date, r->>'domain_bucket',
  array(select e from jsonb_array_elements_text(r->'target_ids') with ordinality as t(e, n) order by n), r->'steps', r->'sources', '0.2.1-draft', 'draft', 'ee170f6e5b7d08240bbbefd4c64b26cd050ea4dbc962a7bcc0c666bb6b14bb4f'
from jsonb_array_elements($j$[{"id":"B-W2-PHONES","version":1,"track_id":"B","title_vi":"Tuần 2 — Điện thoại ở trường","big_question_en":"Should schools ban phones for the whole school day?","big_question_vi":"Trường có nên cấm điện thoại suốt cả ngày học không?","week":2,"date_from":"2026-10-26","date_to":"2026-11-01","domain_bucket":"society","target_ids":["B-L2-CLOZE","B-T1-EXAM-R","B-L1-TRANSFORM-W","B-T2-ASSUME-R","B-T5-SOURCE","B-T7-ARGUE","B-T11-QUALIFY","B-L1-COMPLEX-W","B-L2-PRECISE","B-L4-EXPLAIN-S","B-A3-REVISE"],"steps":[{"step_no":1,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-L2-CLOZE"],"prompt_en":"Read the passage and choose the best answer for each gap. 8 minutes. No dictionary.","time_min":8,"planned_date":"2026-10-26","items":[{"id":"W2-A2-1","kind":"word_form","stem":"Gap (1)","options":["concern","concerned","concerning","concernedly"],"target_id":"B-L2-CLOZE"},{"id":"W2-A2-2","kind":"word_form","stem":"Gap (2)","options":["act","actively","active","activity"],"target_id":"B-L2-CLOZE"},{"id":"W2-A2-3","kind":"gap","stem":"Gap (3)","options":["even after","so that","in order","because of"],"target_id":"B-L2-CLOZE"},{"id":"W2-A2-4","kind":"word_form","stem":"Gap (4)","options":["practice","practise","practically","practical"],"target_id":"B-L2-CLOZE"},{"id":"W2-A2-5","kind":"gap","stem":"Gap (5)","options":["itself","himself","themselves","ourselves"],"target_id":"B-L2-CLOZE"},{"id":"W2-A2-6","kind":"gap","stem":"Gap (6)","options":["involved","invited","agreed","allowed"],"target_id":"B-L2-CLOZE"},{"id":"W2-A2-7","kind":"gap","stem":"Gap (7)","options":["use","sense","matter","need"],"target_id":"B-L2-CLOZE"},{"id":"W2-A2-8","kind":"gap","stem":"Gap (8)","options":["effort","difference","progress","success"],"target_id":"B-L2-CLOZE"}],"self_check_vi":[]},{"step_no":2,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["B-T1-EXAM-R"],"prompt_en":"12 minutes. For questions 3, 4 and 6, also write the paragraph and the first words of the supporting sentence.","time_min":12,"planned_date":"2026-10-27","items":[{"id":"W2-A1-1","kind":"mcq","stem":"What is the passage mainly about?","options":["why smartphones are harmful to teenagers","a class challenge to live without a smartphone for a week, and what students learned","how Linh became a better reader","school rules for using phones"],"target_id":"B-T1-EXAM-R"},{"id":"W2-A1-2","kind":"mcq","stem":"According to paragraph 2, what were students allowed to do during the challenge?","options":["use social media for one hour a day","play games at weekends","use a basic phone to contact their families","watch videos for homework"],"target_id":"B-T1-EXAM-R"},{"id":"W2-A1-3","kind":"mcq","stem":"The word \"abandoned\" in paragraph 3 is closest in meaning to ______. (Write ¶ + supporting sentence.)","options":["stopped doing before finishing","finished quickly","bought","borrowed"],"target_id":"B-T1-EXAM-R"},{"id":"W2-A1-4","kind":"mcq","stem":"Linh's words \"I wasn't cleverer. I just had fewer interruptions\" suggest that ______. (Write ¶ + supporting sentence.)","options":["the challenge made her more intelligent","her friends stopped talking to her","she thinks the challenge was unfair","her better progress came from fewer distractions, not from extra ability"],"target_id":"B-T1-EXAM-R"},{"id":"W2-A1-5","kind":"mcq","stem":"Which of the following is NOT true, according to the passage?","options":["Eleven students did not complete the week.","Most students decided to give up smartphones permanently.","Some students felt left out.","Students who gave up could rejoin the next day."],"target_id":"B-T1-EXAM-R"},{"id":"W2-A1-6","kind":"mcq","stem":"What can be inferred from the last paragraph? (Write ¶ + supporting sentence.)","options":["Linh now controls her phone use with a rule she chose herself.","Linh has stopped using her phone.","Linh's parents made the rule for her.","Linh thinks the challenge failed."],"target_id":"B-T1-EXAM-R"}],"self_check_vi":[]},{"step_no":3,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["B-L1-TRANSFORM-W"],"prompt_en":"Rewrite each sentence so that it means the same as the first one. Use the words given.","time_min":10,"planned_date":"2026-10-27","items":[{"id":"W2-A3-1","kind":"transform","stem":"Students must switch off their phones during lessons. → Phones ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W2-A3-2","kind":"transform","stem":"\"Can I use my phone to check a word in the dictionary?\" Nam asked the teacher. → Nam asked the teacher ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W2-A3-3","kind":"transform","stem":"My sister checked her phone every five minutes in the past, but she doesn't now. → My sister used ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W2-A3-4","kind":"transform","stem":"If you don't put your phone away, you won't be able to concentrate. → Unless ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W2-A3-5","kind":"transform","stem":"My brother designed the app. It helps students plan their revision. → The app ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W2-A3-6","kind":"transform","stem":"If you spend more time on your phone at night, you sleep less. → The more ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W2-A3-7","kind":"transform","stem":"I don't have my own phone, and I'd like one. → I wish ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W2-A3-8","kind":"transform","stem":"The video was so interesting that we watched it twice. → It was such ……","options":[],"target_id":"B-L1-TRANSFORM-W"}],"self_check_vi":[]},{"step_no":4,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-T2-ASSUME-R"],"prompt_en":"Read Sources A and B (10 minutes), then answer the questions (20 minutes).","time_min":15,"planned_date":"2026-10-28","items":[{"id":"W2-B1-1","kind":"open","stem":"Source A says reports of online bullying \"fell from nine… to two\". What does the writer assume this shows? Is that a safe assumption? Quote the words you are using.","options":[],"target_id":"B-T2-ASSUME-R"},{"id":"W2-B1-2","kind":"open","stem":"Find two words or phrases in Source A that make the ban sound good without giving any evidence. What picture of the students who complain does \"Change is never easy\" create?","options":[],"target_id":"B-T2-ASSUME-R"}],"self_check_vi":[]},{"step_no":5,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-T5-SOURCE"],"prompt_en":"Answer questions 1 and 2 about how far you can trust the sources. Write 2–4 sentences for each answer.","time_min":15,"planned_date":"2026-10-28","items":[{"id":"W2-B1-3","kind":"open","stem":"Copy and complete the table for both sources (at least two rows for each): Who wrote it, and why? · How were the figures collected? · When, and over what period? · Can anything else confirm it?","options":[],"target_id":"B-T5-SOURCE"},{"id":"W2-B1-4","kind":"open","stem":"For each source, name one specific limitation and one thing the source can still be used for.","options":[],"target_id":"B-T5-SOURCE"}],"self_check_vi":[]},{"step_no":6,"activity_type":"ACT-CANVAS-ADV","mode":"PRACTICE","purpose":[],"target_ids":["B-T7-ARGUE","B-T11-QUALIFY"],"prompt_en":"Practice question: Should students be allowed to use their phones at break time (but not in lessons)? Canvas with frames, then 80-120 words. Canvas boxes: Question · 1. Your answer (My answer is that …) · 2. Reasons + evidence, each with [Source, ¶] (One reason is that … Source B shows this: \"…\" (¶2).) · 3. Why the evidence supports the reason (This supports my point because …) · 4. Limitation (However, this evidence is limited because …) · 5. Conditional conclusion (So it is likely / possible that …, unless / as long as …)","time_min":20,"planned_date":"2026-10-29","items":[],"self_check_vi":[]},{"step_no":7,"activity_type":"ACT-SOURCE-QA","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Choose A, B, C or D. 10 minutes.","time_min":10,"planned_date":"2026-10-30","items":[{"id":"W2-Q-1","kind":"mcq","stem":"[ch]air / [ch]ild / [ch]emistry / [ch]eap","options":["chair","child","chemistry","cheap"],"target_id":null},{"id":"W2-Q-2","kind":"mcq","stem":"Choose the sentence that is correctly made from these words: students / not / allow / use / their phones / during lessons","options":["Students do not allow to use their phones during lessons.","Students are not allowed to use their phones during lessons.","Students are not allowed using their phones during lessons.","Students not allowed to use their phones during lessons."],"target_id":null},{"id":"W2-Q-3","kind":"mcq","stem":"Stress","options":["advice","purpose","problem","student"],"target_id":null},{"id":"W2-Q-4","kind":"mcq","stem":"Stress","options":["difficult","interesting","beautiful","tomorrow"],"target_id":null},{"id":"W2-Q-5","kind":"mcq","stem":"My brother is used to ______ up early.","options":["get","got","getting","gets"],"target_id":null},{"id":"W2-Q-6","kind":"mcq","stem":"Choose the best order to make a short paragraph: a. However, some students say the rule is hard to follow, despite these benefits. b. Our school has introduced a new rule about phones. c. Under this rule, phones must be switched off and kept in bags during lessons. d. Because of this, most teachers say that lessons now start faster.","options":["b–c–d–a","b–d–c–a","c–b–d–a","b–c–a–d"],"target_id":null},{"id":"W2-Q-7","kind":"mcq","stem":"Lan: \"Thanks for helping me with my project.\" – Minh: \"______\"","options":["You're welcome.","Yes, I do.","That's a good idea.","I'm afraid not."],"target_id":null},{"id":"W2-Q-8","kind":"mcq","stem":"Computer room open after school. Book at least one day in advance.","options":["Students cannot use the computer room after school.","Students can walk in at any time.","Students need to book the day before or earlier.","Bookings must be made on the same day."],"target_id":null}],"self_check_vi":[]},{"step_no":8,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-T7-ARGUE","B-T11-QUALIFY","B-L1-COMPLEX-W","B-L2-PRECISE"],"prompt_en":"Should schools ban phones for the whole school day? 250-300 words, Sources A and B open. Quick Canvas (5') with [Source, ¶] for each reason, then write. Use evidence from both sources, explain how one piece of evidence supports your reason, name one limitation, and end with a conclusion that says how sure you are and what would change your mind.","time_min":45,"planned_date":"2026-10-31","items":[],"self_check_vi":["Câu đầu tiên đã trả lời thẳng câu hỏi chưa?","Mỗi lý do đã có ít nhất một chỗ dẫn từ nguồn (Nguồn A hay B, đoạn mấy) chưa?","Có ít nhất một chỗ bạn giải thích vì sao bằng chứng ấy đỡ cho lý do của mình chưa?","Bạn đã nêu một giới hạn của bằng chứng chưa?","Kết luận đã nói rõ bạn chắc đến đâu (likely, in most cases…) và khi nào thì kết luận sẽ khác (unless…, if…) chưa?","Bài đã đủ 250 từ chưa? Có vài câu phức với which, who, although, if… chưa?","Đọc lại một lượt, chỉ để tìm 3 lỗi bạn hay mắc nhất.","Bạn đã nói được ai viết mỗi nguồn và họ viết để làm gì chưa?"]},{"step_no":9,"activity_type":"ACT-REVISE","mode":"REVISION","purpose":[],"target_ids":["B-A3-REVISE"],"prompt_en":"Read the (max 3) comments. Fix only those places. Underline what you changed and add one line: \"I changed … because …\".","time_min":15,"planned_date":"2026-11-01","items":[],"self_check_vi":["Chỉ sửa những chỗ có gợi ý (tối đa 3), không viết lại cả bài.","Gạch chân chỗ đã sửa và ghi một dòng cuối: \"Mình đã sửa … vì …\"."]},{"step_no":10,"activity_type":"ACT-SPEAK-LIVE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["B-L4-EXPLAIN-S"],"prompt_en":"Read Source A for 2 minutes, then turn it over. No notes this time. Explain the head teacher's argument to your teacher in 2-3 minutes, so that they can say it back in one sentence. Give at least one example.","time_min":12,"planned_date":"2026-11-01","items":[],"self_check_vi":[]}],"sources":[{"id":"B-W2-PHONES-S1","version":1,"title":"A Week Without a Smartphone (exam-style reading)","modality":"text","url":null},{"id":"B-W2-PHONES-S2","version":1,"title":"Phones and sleep (cloze)","modality":"text","url":null},{"id":"B-W2-PHONES-S3","version":1,"title":"Source A — Phones Away, Heads Up","modality":"text","url":null},{"id":"B-W2-PHONES-S4","version":1,"title":"Source B — Ban the Misuse, Not the Phone","modality":"text","url":null}]}]$j$::jsonb) as r
on conflict (id, version) do nothing;

insert into english.template_item_keys(template_id, template_version, item_id, step_no, kind, answer, explanation_vi)
