insert into english.sources(id, version, title, url, author, rights_note, modality, body, source_hash)
select r->>'id', (r->>'version')::int, r->>'title', r->>'url', r->>'author', r->>'rights_note', r->>'modality', r->>'body', r->>'source_hash'
from jsonb_array_elements($j$[{"id":"B-W3-TRANSPORT-S1","version":1,"title":"The Bicycle Bus (exam-style reading)","url":null,"author":"Pilot Kit B author","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"¶1 In some cities, a new kind of \"bus\" has started to appear on the roads on weekday mornings. It has no engine, no driver and no ticket machine. It is a bicycle bus: a group of children who cycle to school together, guided by a few adult volunteers.\n\n¶2 The idea works like an ordinary bus route. The group follows a fixed path and stops at the same corners at the same times, where more children join. By the time it reaches the school gate, a bicycle bus may have grown from five riders to fifty. Because the children ride as one large, visible group, drivers slow down and give them space, which makes many parents feel more comfortable about letting their children cycle.\n\n¶3 Supporters say the benefits go beyond safety. Children arrive at school awake and in a good mood after twenty minutes of exercise. Fewer cars near the school gate mean less traffic and cleaner air for everyone. And for many children, the ride is simply the most enjoyable part of the day.\n\n¶4 Bicycle buses are not without difficulties, however. They depend entirely on volunteers, and when a key parent moves away or changes jobs, a route can disappear. They also work best where the roads are reasonably flat and where at least some cycle lanes exist. In cities with heavy traffic and no safe space for bikes, organisers warn that a bicycle bus should not be started without support from the local authorities.\n\n¶5 Even so, the idea is spreading, largely because it is cheap: all it needs is bicycles, a route and a few adults who are willing to get up early.","source_hash":"d7233fd19e5c86a7d4b69557802fa6dd76ce744b63e045c9d185be45d6ed52f7"},{"id":"B-W3-TRANSPORT-S2","version":1,"title":"Reliable public transport (cloze)","url":null,"author":"Pilot Kit B author","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"Public transport only works if people (1) ______ use it. In many fast-growing cities, the problem is not a lack of buses but a lack of (2) ______: buses get stuck in the same traffic jams as cars, so passengers cannot be sure when they will arrive. One solution is to give buses their own lanes. When buses can move freely, journeys become faster and more (3) ______, and more people are willing to leave their motorbikes at home. However, bus lanes only help if other vehicles are kept (4) ______ of them, which means the rules must be enforced. Another factor is the \"last kilometre\". Even a fast bus is not much use if the nearest stop is a long, hot walk away. Some cities are (5) ______ this problem by adding shaded footpaths and bicycle parking near stations. Fares (6) ______ matter, especially for students and older people, but many passengers say they care at least as much about (7) ______ and comfort. In short, a good transport system is one that people choose because it is convenient, not one they use only (8) ______ they have no other choice.","source_hash":"fbe99ef96b2847fe5cd95a7f1577578fd5abc85f1812363515f5e098bfbe6c97"},{"id":"B-W3-TRANSPORT-S3","version":1,"title":"Source A — Free Rides for Those Who Need Them Most","url":null,"author":"Imagined retired teacher, local newspaper column, October 2026 (invented)","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào. Lanford và Westbrook là thành phố giả định. Nguồn dùng cho bài nói Chủ nhật: thầy/cô KHÔNG đọc trước.","modality":"text","body":"¶1 Our city likes to say that its buses are \"for everyone\". But for many people, they are not. A monthly bus pass in Lanford costs 300,000 dong. For a student or a pensioner, that is a lot of money, and for a family with three children at secondary school it is almost a million dong a month.\n\n¶2 The city has a limited budget for public transport, and it must decide how to spend it. I believe the fairest choice is to make buses free for students, people over sixty and low-income workers. These are the people who depend on buses most, because they cannot afford cars or taxis. In the neighbouring city of Westbrook, where fares for students were removed two years ago, school attendance rose and fewer teenagers rode motorbikes without a licence.\n\n¶3 Some will say that free rides are a gift the city cannot afford. But a city that wants clean air and safe roads cannot afford to keep its poorest residents off the bus.","source_hash":"85882cc0ec5ff095473124f8ec352e9e08a8704f18bbe0ea73848cc6b83c1f12"},{"id":"B-W3-TRANSPORT-S4","version":1,"title":"Source B — A Bus That Never Comes Is Not Cheap","url":null,"author":"Imagined urban-planning student, Lanford public city forum, October 2026 (invented)","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"¶1 Cheaper fares sound fair, but they miss the real problem. On most routes in Lanford, buses come only every 25 to 30 minutes, and they are often late. If you have to wait half an hour, even a free bus is not much use, especially in the rain.\n\n¶2 According to the city transport office's own estimate, removing fares for students, older people and low-income workers would cost about the same as doubling the number of buses on the ten busiest routes. In the office's passenger survey last year, 58 per cent of passengers named waiting time as their biggest complaint; only 21 per cent named the price.\n\n¶3 Better service helps everyone, including the poorest passengers, who often have the longest journeys. Of course, some families genuinely cannot afford the fare, and they should get help. But the city's main investment should go into frequency: a bus every ten minutes would bring more people onto public transport than any discount.","source_hash":"0ef171863580c6a9f99cad6686e3ca526e679f8763097c3fb459e8ba6537b106"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'B-W3-TRANSPORT' and it.version = 1 and it.published_at is not null)
on conflict (id, version) do nothing;

update english.sources set published_at = now()
where version = 1 and id in ('B-W3-TRANSPORT-S1', 'B-W3-TRANSPORT-S2', 'B-W3-TRANSPORT-S3', 'B-W3-TRANSPORT-S4') and published_at is null;

insert into english.inquiry_templates(id, version, track_id, title_vi, big_question_en, big_question_vi, week, date_from, date_to, domain_bucket, target_ids, steps, sources, catalogue_version, status, source_hash)
select r->>'id', (r->>'version')::int, r->>'track_id', r->>'title_vi', r->>'big_question_en', r->>'big_question_vi', (r->>'week')::int,
  (r->>'date_from')::date, (r->>'date_to')::date, r->>'domain_bucket',
  array(select e from jsonb_array_elements_text(r->'target_ids') with ordinality as t(e, n) order by n), r->'steps', r->'sources', '0.2.1-draft', 'draft', 'b7a358212b12fec8bc71acc8fad85d9399f2e4a3bfd19731a9d391975bc09956'
from jsonb_array_elements($j$[{"id":"B-W3-TRANSPORT","version":1,"track_id":"B","title_vi":"Tuần 3 — Giao thông công cộng công bằng (Lanford, giả định)","big_question_en":"Which is the fairer way for Lanford to spend its transport money: free bus fares for students, older people and low-income workers, or more frequent buses for everyone?","big_question_vi":"Thành phố Lanford (giả định) nên dùng ngân sách giao thông để miễn vé xe buýt cho học sinh, người cao tuổi và người thu nhập thấp, hay để tăng chuyến cho mọi người? Cách nào công bằng hơn?","week":3,"date_from":"2026-11-02","date_to":"2026-11-08","domain_bucket":"society","target_ids":["B-T1-EXAM-R","B-L2-CLOZE","B-L1-TRANSFORM-W","B-T1-ARG-R","B-T2-ASSUME-R","B-T7-ARGUE","B-T11-QUALIFY","B-L1-COMPLEX-W","B-L2-PRECISE","B-L4-EXPLAIN-S","B-A3-REVISE"],"steps":[{"step_no":1,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-T1-EXAM-R"],"prompt_en":"12 minutes. For questions 3, 4 and 6, write the paragraph and the first words of the supporting sentence.","time_min":12,"planned_date":"2026-11-02","items":[{"id":"W3-A1-1","kind":"mcq","stem":"What is the passage mainly about?","options":["how to repair a bicycle","a new type of electric bus","a group cycling-to-school scheme, its benefits and its limits","why parents prefer to drive children to school"],"target_id":"B-T1-EXAM-R"},{"id":"W3-A1-2","kind":"mcq","stem":"According to paragraph 2, why do drivers slow down and give the group space?","options":["because the children ride as one large, visible group","because police officers stop the traffic","because there are cycle lanes everywhere","because the volunteers wear uniforms"],"target_id":"B-T1-EXAM-R"},{"id":"W3-A1-3","kind":"mcq","stem":"The word \"visible\" in paragraph 2 is closest in meaning to ______. (Write ¶ + supporting sentence.)","options":["noisy","fast","organised","easy to see"],"target_id":"B-T1-EXAM-R"},{"id":"W3-A1-4","kind":"mcq","stem":"What can be inferred about bicycle buses from paragraph 4? (Write ¶ + supporting sentence.)","options":["They are usually banned by local authorities.","Their future depends on a small number of committed adults.","They need expensive equipment.","They are safest in cities with heavy traffic."],"target_id":"B-T1-EXAM-R"},{"id":"W3-A1-5","kind":"mcq","stem":"Which of the following is NOT mentioned as a benefit of bicycle buses?","options":["lower bus fares for families","exercise before school","less traffic near the school","cleaner air"],"target_id":"B-T1-EXAM-R"},{"id":"W3-A1-6","kind":"mcq","stem":"The word \"largely\" in the last paragraph suggests that ______. (Write ¶ + supporting sentence.)","options":["cost is the only reason the idea is spreading","the routes are getting longer","cost is the main, but not the only, reason the idea is spreading","the idea is spreading slowly"],"target_id":"B-T1-EXAM-R"}],"self_check_vi":[]},{"step_no":2,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["B-L2-CLOZE"],"prompt_en":"Read the passage and choose the best answer for each gap. 8 minutes. No dictionary.","time_min":8,"planned_date":"2026-11-03","items":[{"id":"W3-A2-1","kind":"word_form","stem":"Gap (1)","options":["actual","actually","actuality","act"],"target_id":"B-L2-CLOZE"},{"id":"W3-A2-2","kind":"word_form","stem":"Gap (2)","options":["rely","reliable","reliably","reliability"],"target_id":"B-L2-CLOZE"},{"id":"W3-A2-3","kind":"word_form","stem":"Gap (3)","options":["predict","prediction","predictable","predictably"],"target_id":"B-L2-CLOZE"},{"id":"W3-A2-4","kind":"gap","stem":"Gap (4)","options":["out","off","away","from"],"target_id":"B-L2-CLOZE"},{"id":"W3-A2-5","kind":"gap","stem":"Gap (5)","options":["raising","making","tackling","causing"],"target_id":"B-L2-CLOZE"},{"id":"W3-A2-6","kind":"gap","stem":"Gap (6)","options":["either","also","neither","yet"],"target_id":"B-L2-CLOZE"},{"id":"W3-A2-7","kind":"gap","stem":"Gap (7)","options":["price","colour","fashion","speed"],"target_id":"B-L2-CLOZE"},{"id":"W3-A2-8","kind":"gap","stem":"Gap (8)","options":["because","although","unless","so"],"target_id":"B-L2-CLOZE"}],"self_check_vi":[]},{"step_no":3,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["B-L1-TRANSFORM-W"],"prompt_en":"Rewrite each sentence so that it means the same as the first one. Use the words given.","time_min":10,"planned_date":"2026-11-03","items":[{"id":"W3-A3-1","kind":"transform","stem":"The city has opened two new bus lanes this year. → Two new bus lanes ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W3-A3-2","kind":"transform","stem":"\"The new metro line will open next year,\" the official said. → The official said (that) ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W3-A3-3","kind":"transform","stem":"We missed the bus because we left home late. → If we ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W3-A3-4","kind":"transform","stem":"Taking the bus is cheaper than taking a taxi. → Taking a taxi is not ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W3-A3-5","kind":"transform","stem":"Although the fare is low, many people still prefer motorbikes. → In spite of ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W3-A3-6","kind":"transform","stem":"That woman is a bus driver. Her son is in my class. → That woman ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W3-A3-7","kind":"transform","stem":"We should improve the bus service now. → It's time ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W3-A3-8","kind":"transform","stem":"\"Why don't we take the metro to the museum?\" said Hoa. → Hoa suggested ……","options":[],"target_id":"B-L1-TRANSFORM-W"}],"self_check_vi":[]},{"step_no":4,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-T1-ARG-R","B-T2-ASSUME-R"],"prompt_en":"Read Sources A and B (10 minutes), then answer the questions (20 minutes).","time_min":30,"planned_date":"2026-11-04","items":[{"id":"W3-B1-1","kind":"short","stem":"In one sentence each, what is the main claim of Source A and of Source B?","options":[],"target_id":"B-T1-ARG-R"},{"id":"W3-B1-2","kind":"short","stem":"List three reasons or pieces of evidence used in Source B, with the paragraph.","options":[],"target_id":"B-T1-ARG-R"},{"id":"W3-B1-3a","kind":"mcq","stem":"Which best describes Source B's attitude to helping poorer passengers?","options":["It rejects any help for them.","It accepts some help for families who cannot pay, but puts frequency first.","It thinks fares should be raised.","It has no view on them."],"target_id":"B-T1-ARG-R"},{"id":"W3-B1-3b","kind":"mcq","stem":"Which best describes Source A's attitude to the cost of free rides?","options":["It accepts the cost as worth paying for clean air and safe roads.","It thinks free rides cost nothing.","It says the city should borrow money.","It admits free rides are a mistake."],"target_id":"B-T1-ARG-R"},{"id":"W3-B1-4","kind":"open","stem":"Source A says that in Westbrook \"school attendance rose and fewer teenagers rode motorbikes without a licence\". What does the writer assume about why this happened? Quote the words.","options":[],"target_id":"B-T2-ASSUME-R"},{"id":"W3-B1-5","kind":"open","stem":"Source B uses a survey of passengers. Who was not asked, and what does Source B assume because of this?","options":[],"target_id":"B-T2-ASSUME-R"}],"self_check_vi":[]},{"step_no":5,"activity_type":"ACT-CANVAS-ADV","mode":"PRACTICE","purpose":[],"target_ids":["B-T7-ARGUE","B-T11-QUALIFY"],"prompt_en":"Practice question: Should students travel free on Lanford's buses? Canvas with frames, then 80-120 words. Canvas boxes: Question · 1. Your answer (My answer is that …) · 2. Reasons + evidence, each with [Source, ¶] (One reason is that … Source B shows this: \"…\" (¶2).) · 3. Why the evidence supports the reason (This supports my point because …) · 4. Limitation (However, this evidence is limited because …) · 5. Conditional conclusion (So it is likely / possible that …, unless / as long as …)","time_min":20,"planned_date":"2026-11-05","items":[],"self_check_vi":[]},{"step_no":6,"activity_type":"ACT-SOURCE-QA","mode":"PRACTICE","purpose":[],"target_ids":[],"prompt_en":"Choose A, B, C or D. 10 minutes.","time_min":10,"planned_date":"2026-11-06","items":[{"id":"W3-Q-1","kind":"mcq","stem":"bus[es] / watch[es] / box[es] / stop[s]","options":["buses","watches","boxes","stops"],"target_id":null},{"id":"W3-Q-2","kind":"mcq","stem":"Choose the sentence that is correctly made from these words: the new bus lane / make / journeys / faster / and / more reliable","options":["The new bus lane make journeys faster and more reliable.","The new bus lane makes journeys to be faster and more reliable.","The new bus lane makes journeys faster and more reliably.","The new bus lane makes journeys faster and more reliable."],"target_id":null},{"id":"W3-Q-3","kind":"mcq","stem":"Stress","options":["traffic","police","travel","station"],"target_id":null},{"id":"W3-Q-4","kind":"mcq","stem":"Stress","options":["pollution","passenger","family","motorbike"],"target_id":null},{"id":"W3-Q-5","kind":"mcq","stem":"If it ______ tomorrow, we will take the bus instead of cycling.","options":["will rain","rained","rains","would rain"],"target_id":null},{"id":"W3-Q-6","kind":"mcq","stem":"Choose the best order to make a short paragraph: a. Because of this faster service, more people are now leaving their motorbikes at home. b. The city has built three new bus lanes this year. c. Buses can move freely in these lanes, so journeys are quicker and more reliable. d. However, the lanes only work if other vehicles stay out of them.","options":["b–a–c–d","b–c–a–d","b–c–d–a","c–b–a–d"],"target_id":null},{"id":"W3-Q-7","kind":"mcq","stem":"Passenger: \"Excuse me, does this bus go to the city library?\" – Driver: \"______\"","options":["Yes, I'd like to.","You're welcome.","Not at all, thanks.","No, it doesn't. You need the number 12."],"target_id":null},{"id":"W3-Q-8","kind":"mcq","stem":"BUS LANE 6-9 a.m. Monday to Friday. Cars and motorbikes must not enter.","options":["Cars can use the lane on weekday mornings.","Cars and motorbikes cannot use the lane from 6 to 9 a.m. on weekdays.","The lane is closed at weekends.","Motorbikes can use the lane at any time."],"target_id":null}],"self_check_vi":[]},{"step_no":7,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-T7-ARGUE","B-T11-QUALIFY","B-L1-COMPLEX-W","B-L2-PRECISE"],"prompt_en":"Which is the fairer way for Lanford to spend its transport money: free bus fares for students, older people and low-income workers, or more frequent buses for everyone? 250-300 words, Sources A and B open. Say what \"fair\" means in your answer (for example: helping those with least money, or giving everyone a better service). Use evidence from both sources, name one limitation, and end with a conclusion that says how sure you are and under what condition you would choose the other option.","time_min":45,"planned_date":"2026-11-07","items":[],"self_check_vi":["Câu đầu tiên đã trả lời thẳng câu hỏi chưa?","Mỗi lý do đã có ít nhất một chỗ dẫn từ nguồn (Nguồn A hay B, đoạn mấy) chưa?","Có ít nhất một chỗ bạn giải thích vì sao bằng chứng ấy đỡ cho lý do của mình chưa?","Bạn đã nêu một giới hạn của bằng chứng chưa?","Kết luận đã nói rõ bạn chắc đến đâu (likely, in most cases…) và khi nào thì kết luận sẽ khác (unless…, if…) chưa?","Bài đã đủ 250 từ chưa? Có vài câu phức với which, who, although, if… chưa?","Đọc lại một lượt, chỉ để tìm 3 lỗi bạn hay mắc nhất.","Kết luận của bạn có nói khi nào bạn sẽ chọn phương án kia không?"]},{"step_no":8,"activity_type":"ACT-REVISE","mode":"REVISION","purpose":[],"target_ids":["B-A3-REVISE"],"prompt_en":"Read the (max 3) comments. Fix only those places. Underline what you changed and add one line: \"I changed … because …\".","time_min":15,"planned_date":"2026-11-08","items":[],"self_check_vi":["Chỉ sửa những chỗ có gợi ý (tối đa 3), không viết lại cả bài.","Gạch chân chỗ đã sửa và ghi một dòng cuối: \"Mình đã sửa … vì …\"."]},{"step_no":9,"activity_type":"ACT-SPEAK-LIVE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["B-L4-EXPLAIN-S"],"prompt_en":"Read Source A for 2 minutes, turn it over, no notes. Explain the writer's argument so your teacher can say it back in one sentence. Give one example.","time_min":12,"planned_date":"2026-11-08","items":[],"self_check_vi":[]}],"sources":[{"id":"B-W3-TRANSPORT-S1","version":1,"title":"The Bicycle Bus (exam-style reading)","modality":"text","url":null},{"id":"B-W3-TRANSPORT-S2","version":1,"title":"Reliable public transport (cloze)","modality":"text","url":null},{"id":"B-W3-TRANSPORT-S3","version":1,"title":"Source A — Free Rides for Those Who Need Them Most","modality":"text","url":null},{"id":"B-W3-TRANSPORT-S4","version":1,"title":"Source B — A Bus That Never Comes Is Not Cheap","modality":"text","url":null}]}]$j$::jsonb) as r
on conflict (id, version) do nothing;

insert into english.template_item_keys(template_id, template_version, item_id, step_no, kind, answer, explanation_vi)
select 'B-W3-TRANSPORT', 1, r->>'item_id', (r->>'step_no')::int, r->>'kind', r->>'answer', r->>'explanation_vi'
from jsonb_array_elements($j$[{"step_no":1,"item_id":"W3-A1-1","kind":"answer","answer":"C","explanation_vi":null},{"step_no":1,"item_id":"W3-A1-2","kind":"answer","answer":"A","explanation_vi":null},{"step_no":1,"item_id":"W3-A1-3","kind":"answer","answer":"D","explanation_vi":"¶2 \"Because the children ride as one large, visible group, drivers slow down\"."},{"step_no":1,"item_id":"W3-A1-4","kind":"answer","answer":"B","explanation_vi":"¶4 \"They depend entirely on volunteers… a route can disappear\"."},{"step_no":1,"item_id":"W3-A1-5","kind":"answer","answer":"A","explanation_vi":null},{"step_no":1,"item_id":"W3-A1-6","kind":"answer","answer":"C","explanation_vi":"¶5 \"largely because it is cheap\"."},{"step_no":1,"item_id":"step-1:note","kind":"note","answer":null,"explanation_vi":"Thứ Hai 2/11 (ở nhà) · A1 đọc hiểu (274 từ). Sau đó 5' sổ lỗi."},{"step_no":2,"item_id":"W3-A2-1","kind":"answer","answer":"B","explanation_vi":"Trạng từ bổ nghĩa cho use."},{"step_no":2,"item_id":"W3-A2-2","kind":"answer","answer":"D","explanation_vi":"a lack of + danh từ."},{"step_no":2,"item_id":"W3-A2-3","kind":"answer","answer":"C","explanation_vi":"faster and more + tính từ."},{"step_no":2,"item_id":"W3-A2-4","kind":"answer","answer":"A","explanation_vi":"kept out of them."},{"step_no":2,"item_id":"W3-A2-5","kind":"answer","answer":"C","explanation_vi":"tackle a problem = giải quyết."},{"step_no":2,"item_id":"W3-A2-6","kind":"answer","answer":"B","explanation_vi":"Fares also matter."},{"step_no":2,"item_id":"W3-A2-7","kind":"answer","answer":"D","explanation_vi":"price sai về logic vì câu trước đã nói đến fares."},{"step_no":2,"item_id":"W3-A2-8","kind":"answer","answer":"A","explanation_vi":"only because they have no other choice."},{"step_no":2,"item_id":"step-2:note","kind":"note","answer":null,"explanation_vi":"Thứ Ba 3/11, trong buổi, thầy/cô duyệt · A2 điền đoạn văn (184 từ). Dạng từ: 1, 2, 3."},{"step_no":3,"item_id":"W3-A3-1","kind":"answer","answer":"Two new bus lanes have been opened by the city this year.","explanation_vi":"Cũng chấp nhận: …have been opened this year by the city · Không chấp nhận: were opened; have opened; bỏ by the city"},{"step_no":3,"item_id":"W3-A3-2","kind":"answer","answer":"The official said (that) the new metro line would open the following year.","explanation_vi":"Cũng chấp nhận: …the next year / the year after · Không chấp nhận: will open; giữ next year"},{"step_no":3,"item_id":"W3-A3-3","kind":"answer","answer":"If we hadn't left home late, we wouldn't have missed the bus.","explanation_vi":"Cũng chấp nhận: …had not… would not have… · If we had left home earlier, we wouldn't have missed / would have caught the bus. · Không chấp nhận: If we didn't leave…; …wouldn't miss…"},{"step_no":3,"item_id":"W3-A3-4","kind":"answer","answer":"Taking a taxi is not as cheap as taking the bus.","explanation_vi":"Cũng chấp nhận: …not so cheap as… · Không chấp nhận: …not cheaper than… (khác nghĩa)"},{"step_no":3,"item_id":"W3-A3-5","kind":"answer","answer":"In spite of the low fare, many people still prefer motorbikes.","explanation_vi":"Cũng chấp nhận: In spite of the fact that the fare is low, … · In spite of the fare being low, … · Không chấp nhận: In spite of the fare is low"},{"step_no":3,"item_id":"W3-A3-6","kind":"answer","answer":"That woman, whose son is in my class, is a bus driver.","explanation_vi":"Cũng chấp nhận: (không có dấu phẩy cũng được) · Không chấp nhận: who her son; whose her son; which son"},{"step_no":3,"item_id":"W3-A3-7","kind":"answer","answer":"It's time we improved the bus service.","explanation_vi":"Cũng chấp nhận: It's time for us to improve the bus service. · …(now) · Không chấp nhận: It's time we improve…"},{"step_no":3,"item_id":"W3-A3-8","kind":"answer","answer":"Hoa suggested taking the metro to the museum.","explanation_vi":"Cũng chấp nhận: Hoa suggested (that) we/they (should) take the metro to the museum. · Không chấp nhận: suggested us to take; suggested to take"},{"step_no":3,"item_id":"step-3:note","kind":"note","answer":null,"explanation_vi":"Thứ Ba 3/11, trong buổi · A3 viết lại câu."},{"step_no":4,"item_id":"W3-B1-1","kind":"sealed","answer":"A: the fairest choice is free buses for students, people over sixty and low-income workers. B: the money should mainly go into more frequent buses, because waiting time is the real problem.","explanation_vi":"Cần đúng cả hai (c1 B-T1-ARG-R)."},{"step_no":4,"item_id":"W3-B1-2","kind":"sealed","answer":"3 trong: xe 25-30 phút một chuyến, hay trễ (¶1) · miễn vé tốn ngang gấp đôi xe ở 10 tuyến đông nhất (¶2) · 58% than thời gian chờ, 21% than giá (¶2) · dịch vụ tốt giúp cả người nghèo, vốn đi xa nhất (¶3).","explanation_vi":"c2 B-T1-ARG-R."},{"step_no":4,"item_id":"W3-B1-3a","kind":"answer","answer":"B","explanation_vi":"Cần đúng cả 3a và 3b (c3)."},{"step_no":4,"item_id":"W3-B1-3b","kind":"answer","answer":"A","explanation_vi":"¶3."},{"step_no":4,"item_id":"W3-B1-4","kind":"sealed","answer":"The writer assumes that removing student fares CAUSED both changes, though other causes are possible (laws, schools, coincidence). Quote ¶2 \"where fares for students were removed two years ago, school attendance rose…\".","explanation_vi":"c1-c3 B-T2-ASSUME-R."},{"step_no":4,"item_id":"W3-B1-5","kind":"sealed","answer":"People who do not ride the bus (perhaps because of the price) were not asked. Source B assumes current passengers' views represent the whole city, so it may underestimate the role of price. Quote ¶2 \"58 per cent of passengers…\".","explanation_vi":"Căn cứ thứ hai cho B-T2-ASSUME-R. Lưu ý (FIXLIST): câu này cũng chạm yếu tố \"phương pháp\" của B-T5-SOURCE → ghi vào nhật ký luyện (exposure) để tính khoảng cách bài ôn lại."},{"step_no":4,"item_id":"step-4:note","kind":"note","answer":null,"explanation_vi":"Thứ Tư 4/11 · B-T1-ARG-R và B-T2-ASSUME-R bối cảnh thứ 2."},{"step_no":5,"item_id":"step-5:note","kind":"note","answer":null,"explanation_vi":"Thứ Năm 5/11 · Luyện tập."},{"step_no":6,"item_id":"W3-Q-1","kind":"answer","answer":"D","explanation_vi":"stops /s/, còn lại /ɪz/."},{"step_no":6,"item_id":"W3-Q-2","kind":"answer","answer":"D","explanation_vi":"Dựng câu: makes (chia ngôi 3 số ít) + tân ngữ + tính từ. A sai chia động từ; B thừa to be; C dùng trạng từ reliably sau make + tân ngữ."},{"step_no":6,"item_id":"W3-Q-3","kind":"answer","answer":"B","explanation_vi":"police nhấn âm 2."},{"step_no":6,"item_id":"W3-Q-4","kind":"answer","answer":"A","explanation_vi":"pollution nhấn âm 2."},{"step_no":6,"item_id":"W3-Q-5","kind":"answer","answer":"C","explanation_vi":"Điều kiện loại 1."},{"step_no":6,"item_id":"W3-Q-6","kind":"answer","answer":"B","explanation_vi":"b (nêu việc) – c (these lanes, nhanh hơn) – a (Because of this faster service) – d (However)."},{"step_no":6,"item_id":"W3-Q-7","kind":"answer","answer":"D","explanation_vi":null},{"step_no":6,"item_id":"W3-Q-8","kind":"answer","answer":"B","explanation_vi":"ĐÃ SỬA (FIXLIST ⚪): phương án B cũ \"Only buses may use the lane…\" là suy diễn thêm; thay bằng câu bám sát biển."},{"step_no":6,"item_id":"step-6:note","kind":"note","answer":null,"explanation_vi":"Thứ Sáu 6/11 · Luyện nhanh (không ghi CSV)."},{"step_no":7,"item_id":"step-7:note","kind":"note","answer":null,"explanation_vi":"Thứ Bảy 7/11 · 45'."},{"step_no":8,"item_id":"step-8:note","kind":"note","answer":null,"explanation_vi":"Chủ nhật 8/11 chiều · cùng learning_family FAM-B-TR-1. Câu 5 thứ Tư 4/11 và góp ý bài viết tuần 3 chạm yếu tố \"phương pháp\" của B-T5-SOURCE, nên mốc last_practice_date cho B-T5-SOURCE là 2026-11-08 (bài ôn lại sớm nhất 22/11)."},{"step_no":9,"item_id":"step-9:note","kind":"note","answer":null,"explanation_vi":"Chủ nhật 8/11, trong buổi (≈ 12'). Ý chính: \"The writer argues that the fairest use of Lanford's limited transport money is free buses for students, older people and low-income workers, because they depend on buses most and passes are a heavy cost for them; the writer points to a neighbouring city where removing student fares seemed to help.\""}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'B-W3-TRANSPORT' and it.version = 1 and it.published_at is not null)
on conflict (template_id, template_version, item_id) do nothing;

update english.inquiry_templates set status = 'published', published_at = now()
where id = 'B-W3-TRANSPORT' and version = 1 and published_at is null;

-- Inquiry template B-W4-AI-HOMEWORK v1 (published after its sources and answer keys are in)
insert into english.sources(id, version, title, url, author, rights_note, modality, body, source_hash)
select r->>'id', (r->>'version')::int, r->>'title', r->>'url', r->>'author', r->>'rights_note', r->>'modality', r->>'body', r->>'source_hash'
from jsonb_array_elements($j$[{"id":"B-W4-AI-HOMEWORK-S1","version":1,"title":"When Calculators Came to Class (exam-style reading)","url":null,"author":"Pilot Kit B author","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"¶1 When cheap pocket calculators first appeared in shops, many teachers were alarmed. If a machine could do arithmetic in a second, they asked, why would any child bother to learn their times tables? Some schools banned calculators completely. Others allowed them only in the final years of secondary school.\n\n¶2 Over time, a more balanced view developed. Most teachers today agree that students still need to understand how numbers work and to be able to estimate an answer in their heads. Without this understanding, a student who presses the wrong button will not notice that the answer is ridiculous. At the same time, the calculator frees students from long, repetitive calculations, so they can spend more time on the reasoning behind a problem.\n\n¶3 The lesson from this debate is not that every new tool is harmless, nor that every new tool is a threat. Rather, it is that a tool changes what we need to learn. When calculators arrived, mental arithmetic became less important for getting exact answers but more important for checking whether an answer made sense.\n\n¶4 Today, a similar debate is taking place about chatbots that can write essays and explain homework in seconds. Some people fear that students will stop thinking for themselves; others see a tireless personal tutor. If the history of the calculator is any guide, the answer will depend less on the tool itself than on the rules and habits that grow up around it. Students who use the tool to check and extend their thinking are likely to benefit; those who use it to avoid thinking are not.","source_hash":"8346bd910df2fd19e0bf258d436a19972f285907c999acab9c7f213ed0b1b8ad"},{"id":"B-W4-AI-HOMEWORK-S2","version":1,"title":"Chatbots as homework helpers (cloze)","url":null,"author":"Pilot Kit B author","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"Some schools are now testing chatbots as homework helpers. The idea is that a student who is stuck at ten o'clock at night can ask for a hint instead of (1) ______ up. Supporters say this is especially (2) ______ for students whose parents cannot help with difficult subjects. However, teachers point out that chatbots sometimes give answers that sound (3) ______ but are wrong. For this reason, students are taught to treat the chatbot (4) ______ a study partner, not as a teacher who is always right. In one school's guidelines, students must first try a problem on their own, then ask the chatbot to explain only the step they do not understand. The school says the aim is not to stop students from using new technology, but to make sure that it (5) ______ their learning rather than replacing it. Early feedback from students has been mostly (6) ______, although some admit that it is tempting to ask for the full answer when they are tired. The school plans to (7) ______ the guidelines at the end of the year and will make changes (8) ______ necessary.","source_hash":"1533407cb06fa50ef9b4a8d440b1b2e76e77dab690a749bd22272cbe6aa51745"},{"id":"B-W4-AI-HOMEWORK-S3","version":1,"title":"Source A — My Night-Time Tutor","url":null,"author":"Imagined grade-10 student, personal study blog, October 2026 (invented)","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào.","modality":"text","body":"¶1 I used to dread maths homework. If I got stuck at ten at night, there was nobody to ask: my parents were tired, and my tutor only comes on Saturdays. This term, I started using an AI chatbot, and it has changed everything.\n\n¶2 I never ask it for the answer. Instead, I type in my working and ask it where my mistake is, or I ask it to explain a step in a different way. Sometimes I ask it to give me three similar problems so I can practise. I use it for about thirty minutes, three evenings a week. My maths test scores went from 6.5 at the start of the term to 8 in the mid-term test.\n\n¶3 A chatbot is like a patient tutor who never gets tired. Banning AI completely would be pointless, because students will use it anyway. Schools should teach us to use it well: ask for explanations, not answers.","source_hash":"e43c3679151ba98262306ae961f239f3b56407ef344b9d8413441a841fd462c5"},{"id":"B-W4-AI-HOMEWORK-S4","version":1,"title":"Source B — When the Machine Writes, Who Learns?","url":null,"author":"Imagined English teacher, school newsletter for parents, October 2026 (invented)","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào. Nguồn dùng cho bài nói Chủ nhật: thầy/cô KHÔNG đọc trước.","modality":"text","body":"¶1 This term I noticed that several homework essays in my grade-9 class were suddenly fluent, well organised and strangely similar. When I asked, some students admitted they had used a chatbot to write a first draft.\n\n¶2 So I tried a small comparison. Of the 36 students in the class, 14 said they had used a chatbot for their essays during the previous month. In an in-class essay test, written without any devices, those 14 students scored on average 1.5 points lower than the others.\n\n¶3 I must be careful here: students chose for themselves whether to use the chatbot, and those who did may have been weaker writers to begin with. It is one class over one month. But the pattern worries me. When the machine does the thinking, the student just copies, and chatbots will make lazy students lazier.\n\n¶4 I am not calling for a ban. Students may use AI to check grammar or explain a word after they have written their own draft. But the first draft must be theirs.","source_hash":"fdac83296204e65d3e1f5743a9840456b841d9365e95e2ce714e7b0bf115c433"},{"id":"B-W4-AI-HOMEWORK-S5","version":1,"title":"Source C — TaskNest press release","url":null,"author":"Imagined app company, website press release, September 2026 (invented)","rights_note":"Tự soạn cho khóa học (Pilot Kit B v0.2.1); người viết, trường, thành phố và mọi con số là giả định. Không chép từ đề thi hay ấn phẩm nào. Công ty và app là giả định.","modality":"text","body":"\"Students who use TaskNest finish their homework 40% faster! In our survey of 500 app users, 9 out of 10 said they felt less stressed after one month. Teachers love it too. Download TaskNest today and take control of your evenings.\"","source_hash":"48b85d4fb15702a4f11af00ff391d5f2630da8e67546f7e781d0be62d76a99d5"}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'B-W4-AI-HOMEWORK' and it.version = 1 and it.published_at is not null)
on conflict (id, version) do nothing;

update english.sources set published_at = now()
where version = 1 and id in ('B-W4-AI-HOMEWORK-S1', 'B-W4-AI-HOMEWORK-S2', 'B-W4-AI-HOMEWORK-S3', 'B-W4-AI-HOMEWORK-S4', 'B-W4-AI-HOMEWORK-S5') and published_at is null;

insert into english.inquiry_templates(id, version, track_id, title_vi, big_question_en, big_question_vi, week, date_from, date_to, domain_bucket, target_ids, steps, sources, catalogue_version, status, source_hash)
select r->>'id', (r->>'version')::int, r->>'track_id', r->>'title_vi', r->>'big_question_en', r->>'big_question_vi', (r->>'week')::int,
  (r->>'date_from')::date, (r->>'date_to')::date, r->>'domain_bucket',
  array(select e from jsonb_array_elements_text(r->'target_ids') with ordinality as t(e, n) order by n), r->'steps', r->'sources', '0.2.1-draft', 'draft', '36eeac4d15282b36c3385f0e1aab182f4ac61f463996d1ce90810d7451c4d92c'
from jsonb_array_elements($j$[{"id":"B-W4-AI-HOMEWORK","version":1,"track_id":"B","title_vi":"Tuần 4 — AI trong học tập","big_question_en":"Should grade-9 students be allowed to use AI chatbots for homework? If so, under what conditions?","big_question_vi":"Học sinh lớp 9 có nên được dùng chatbot AI khi làm bài tập về nhà không? Nếu có, với điều kiện gì?","week":4,"date_from":"2026-11-09","date_to":"2026-11-15","domain_bucket":"society","target_ids":["B-T1-EXAM-R","B-L2-CLOZE","B-L1-TRANSFORM-W","B-T2-ASSUME-R","B-T5-DATAOP","B-T5-SOURCE","B-T7-ARGUE","B-T11-QUALIFY","B-L1-COMPLEX-W","B-L2-PRECISE","B-L4-EXPLAIN-S","B-A3-REVISE"],"steps":[{"step_no":1,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-T1-EXAM-R"],"prompt_en":"12 minutes. For questions 3, 4 and 6, write the paragraph and the first words of the supporting sentence.","time_min":12,"planned_date":"2026-11-09","items":[{"id":"W4-A1-1","kind":"mcq","stem":"What is the passage mainly about?","options":["what the calculator debate can teach us about new tools such as chatbots","the history of the times tables","how chatbots write essays","why calculators should be banned in schools"],"target_id":"B-T1-EXAM-R"},{"id":"W4-A1-2","kind":"mcq","stem":"According to paragraph 2, why do students still need to understand how numbers work?","options":["because calculators are expensive","because exams do not allow calculators","so that they notice when an answer is obviously wrong","so that they can repair calculators"],"target_id":"B-T1-EXAM-R"},{"id":"W4-A1-3","kind":"mcq","stem":"The word \"ridiculous\" in paragraph 2 is closest in meaning to ______. (Write ¶ + supporting sentence.)","options":["correct","clearly wrong or silly","long","difficult"],"target_id":"B-T1-EXAM-R"},{"id":"W4-A1-4","kind":"mcq","stem":"What does the writer suggest in paragraph 3 about the arrival of calculators? (Write ¶ + supporting sentence.)","options":["Mental arithmetic became useless.","Students became worse at maths.","All teachers accepted calculators immediately.","The skills students needed changed rather than disappeared."],"target_id":"B-T1-EXAM-R"},{"id":"W4-A1-5","kind":"mcq","stem":"According to paragraph 4, how do some people see chatbots?","options":["as a cheap calculator","as a tireless personal tutor","as a replacement for schools","as a tool for checking spelling only"],"target_id":"B-T1-EXAM-R"},{"id":"W4-A1-6","kind":"mcq","stem":"The writer would most likely agree that ______. (Write ¶ + supporting sentence.)","options":["how students use chatbots matters more than whether they have them","chatbots should be banned in all schools","chatbots are completely harmless","calculators were a mistake"],"target_id":"B-T1-EXAM-R"}],"self_check_vi":[]},{"step_no":2,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-L2-CLOZE"],"prompt_en":"Read the passage and choose the best answer for each gap. 8 minutes. No dictionary.","time_min":8,"planned_date":"2026-11-09","items":[{"id":"W4-A2-1","kind":"gap","stem":"Gap (1)","options":["taking","making","giving","putting"],"target_id":"B-L2-CLOZE"},{"id":"W4-A2-2","kind":"word_form","stem":"Gap (2)","options":["use","useful","usefully","usefulness"],"target_id":"B-L2-CLOZE"},{"id":"W4-A2-3","kind":"word_form","stem":"Gap (3)","options":["convince","convincing","convinced","convincingly"],"target_id":"B-L2-CLOZE"},{"id":"W4-A2-4","kind":"gap","stem":"Gap (4)","options":["as","by","for","with"],"target_id":"B-L2-CLOZE"},{"id":"W4-A2-5","kind":"gap","stem":"Gap (5)","options":["stops","supports","replaces","ends"],"target_id":"B-L2-CLOZE"},{"id":"W4-A2-6","kind":"word_form","stem":"Gap (6)","options":["position","positivity","positive","positively"],"target_id":"B-L2-CLOZE"},{"id":"W4-A2-7","kind":"gap","stem":"Gap (7)","options":["review","remind","reply","retire"],"target_id":"B-L2-CLOZE"},{"id":"W4-A2-8","kind":"gap","stem":"Gap (8)","options":["unless","if","so","because"],"target_id":"B-L2-CLOZE"}],"self_check_vi":[]},{"step_no":3,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["B-L1-TRANSFORM-W"],"prompt_en":"Rewrite each sentence so that it means the same as the first one. Use the words given.","time_min":10,"planned_date":"2026-11-10","items":[{"id":"W4-A3-1","kind":"transform","stem":"People believe that AI will change the way we learn. → It is believed ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W4-A3-2","kind":"transform","stem":"\"Don't copy answers from a chatbot,\" the teacher told us. → The teacher told us ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W4-A3-3","kind":"transform","stem":"You should check the facts, or you may end up believing false information. → If you ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W4-A3-4","kind":"transform","stem":"My old dictionary was less useful than this app. → This app is ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W4-A3-5","kind":"transform","stem":"A group of students built this chatbot last year. → This chatbot ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W4-A3-6","kind":"transform","stem":"It is important to ask good questions. → Asking ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W4-A3-7","kind":"transform","stem":"She uses AI to plan her revision. This saves her a lot of time. → She uses AI to plan her revision, which ……","options":[],"target_id":"B-L1-TRANSFORM-W"},{"id":"W4-A3-8","kind":"transform","stem":"I regret not checking the chatbot's answer. → I wish ……","options":[],"target_id":"B-L1-TRANSFORM-W"}],"self_check_vi":[]},{"step_no":4,"activity_type":"ACT-SOURCE-QA","mode":"INDEPENDENT_CHECK","purpose":["delayed_check"],"target_ids":["B-T5-DATAOP","B-T2-ASSUME-R"],"prompt_en":"Read Sources A and B (10 minutes). Answer questions 1-2 first and hand them in; then answer questions 3-4.","time_min":35,"planned_date":"2026-11-11","items":[{"id":"W4-B1-1i","kind":"mcq","stem":"\"My maths test scores went from 6.5 at the start of the term to 8 in the mid-term test.\" (A)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W4-B1-1ii","kind":"mcq","stem":"\"A chatbot is like a patient tutor who never gets tired.\" (A)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W4-B1-1iii","kind":"mcq","stem":"\"Those 14 students scored on average 1.5 points lower than the others.\" (B)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W4-B1-1iv","kind":"mcq","stem":"\"When the machine does the thinking, the student just copies.\" (B)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W4-B1-1v","kind":"mcq","stem":"\"I use it for about thirty minutes, three evenings a week.\" (A)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W4-B1-1vi","kind":"mcq","stem":"\"Banning AI completely would be pointless.\" (A)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W4-B1-1vii","kind":"mcq","stem":"\"Of the 36 students in the class, 14 said they had used a chatbot for their essays during the previous month.\" (B)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W4-B1-1viii","kind":"mcq","stem":"\"Chatbots will make lazy students lazier.\" (B)","options":["D (data/evidence)","C (commentary/interpretation)"],"target_id":"B-T5-DATAOP"},{"id":"W4-B1-2","kind":"open","stem":"Choose two statements you marked C. For each, explain in 1-2 sentences why it is commentary, not data.","options":[],"target_id":"B-T5-DATAOP"},{"id":"W4-B1-3","kind":"open","stem":"Source A's writer says their maths scores went from 6.5 to 8. What does the writer assume caused this? Name one other possible cause. Quote the words.","options":[],"target_id":"B-T2-ASSUME-R"},{"id":"W4-B1-4","kind":"open","stem":"In Source B, ¶3, the teacher first says she \"must be careful\", then writes \"When the machine does the thinking, the student just copies\". What does this second sentence assume about all chatbot use? Quote the words.","options":[],"target_id":"B-T2-ASSUME-R"}],"self_check_vi":[]},{"step_no":5,"activity_type":"ACT-CANVAS-ADV","mode":"PRACTICE","purpose":[],"target_ids":["B-T7-ARGUE","B-T11-QUALIFY"],"prompt_en":"Practice question: Should students be allowed to use AI to check their English essays? Fill in the Canvas with frames only (no paragraph this week). Canvas boxes: Question · 1. Your answer (My answer is that …) · 2. Reasons + evidence, each with [Source, ¶] (One reason is that … Source B shows this: \"…\" (¶2).) · 3. Why the evidence supports the reason (This supports my point because …) · 4. Limitation (However, this evidence is limited because …) · 5. Conditional conclusion (So it is likely / possible that …, unless / as long as …)","time_min":10,"planned_date":"2026-11-12","items":[],"self_check_vi":[]},{"step_no":6,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":[],"target_ids":["B-T7-ARGUE","B-T11-QUALIFY","B-L1-COMPLEX-W","B-L2-PRECISE"],"prompt_en":"Should grade-9 students be allowed to use AI chatbots for homework? If so, under what conditions? 250-300 words, Sources A and B open. Give your position and, if you say \"yes\", at least one clear condition. Use evidence from both sources, explain how one piece of evidence supports your reason, name one limitation of the evidence (Source B admits some of its own; what does Source A leave out?), and end with a conclusion that says how sure you are. No dictionary, no spell-check, no AI.","time_min":45,"planned_date":"2026-11-14","items":[],"self_check_vi":["Câu đầu tiên đã trả lời thẳng câu hỏi chưa?","Mỗi lý do đã có ít nhất một chỗ dẫn từ nguồn (Nguồn A hay B, đoạn mấy) chưa?","Có ít nhất một chỗ bạn giải thích vì sao bằng chứng ấy đỡ cho lý do của mình chưa?","Bạn đã nêu một giới hạn của bằng chứng chưa?","Kết luận đã nói rõ bạn chắc đến đâu (likely, in most cases…) và khi nào thì kết luận sẽ khác (unless…, if…) chưa?","Bài đã đủ 250 từ chưa? Có vài câu phức với which, who, although, if… chưa?","Đọc lại một lượt, chỉ để tìm 3 lỗi bạn hay mắc nhất.","Bạn đã dùng điểm yếu mà Nguồn B tự thừa nhận, và chỉ ra điều Nguồn A bỏ qua chưa?"]},{"step_no":7,"activity_type":"ACT-REVISE","mode":"REVISION","purpose":[],"target_ids":["B-A3-REVISE"],"prompt_en":"Read the (max 3) comments. Fix only those places. Underline what you changed and add one line: \"I changed … because …\".","time_min":15,"planned_date":"2026-11-15","items":[],"self_check_vi":["Chỉ sửa những chỗ có gợi ý (tối đa 3), không viết lại cả bài.","Gạch chân chỗ đã sửa và ghi một dòng cuối: \"Mình đã sửa … vì …\"."]},{"step_no":8,"activity_type":"ACT-SPEAK-LIVE","mode":"INDEPENDENT_CHECK","purpose":["checkpoint"],"target_ids":["B-L4-EXPLAIN-S"],"prompt_en":"Read Source B for 2 minutes, turn it over, no notes. Explain the teacher's argument, including what she is careful about, so your teacher can say it back in one sentence. Give one example.","time_min":12,"planned_date":"2026-11-15","items":[],"self_check_vi":[]},{"step_no":9,"activity_type":"ACT-WRITE","mode":"INDEPENDENT_CHECK","purpose":["delayed_check"],"target_ids":["B-T5-SOURCE"],"prompt_en":"Read Source C. 1. How far can you trust Source C? Use at least two factors. 2. Name one specific limitation, and one thing Source C can still be used for.","time_min":10,"planned_date":null,"items":[{"id":"W4-C-1","kind":"open","stem":"How far can you trust Source C? Use at least two factors (who wrote it and why, how the figures were collected, when and over what period, whether anything else confirms it).","options":[],"target_id":"B-T5-SOURCE"},{"id":"W4-C-2","kind":"open","stem":"Name one specific limitation, and one thing Source C can still be used for.","options":[],"target_id":"B-T5-SOURCE"}],"self_check_vi":[]}],"sources":[{"id":"B-W4-AI-HOMEWORK-S1","version":1,"title":"When Calculators Came to Class (exam-style reading)","modality":"text","url":null},{"id":"B-W4-AI-HOMEWORK-S2","version":1,"title":"Chatbots as homework helpers (cloze)","modality":"text","url":null},{"id":"B-W4-AI-HOMEWORK-S3","version":1,"title":"Source A — My Night-Time Tutor","modality":"text","url":null},{"id":"B-W4-AI-HOMEWORK-S4","version":1,"title":"Source B — When the Machine Writes, Who Learns?","modality":"text","url":null},{"id":"B-W4-AI-HOMEWORK-S5","version":1,"title":"Source C — TaskNest press release","modality":"text","url":null}]}]$j$::jsonb) as r
on conflict (id, version) do nothing;

insert into english.template_item_keys(template_id, template_version, item_id, step_no, kind, answer, explanation_vi)
select 'B-W4-AI-HOMEWORK', 1, r->>'item_id', (r->>'step_no')::int, r->>'kind', r->>'answer', r->>'explanation_vi'
from jsonb_array_elements($j$[{"step_no":1,"item_id":"W4-A1-1","kind":"answer","answer":"A","explanation_vi":null},{"step_no":1,"item_id":"W4-A1-2","kind":"answer","answer":"C","explanation_vi":null},{"step_no":1,"item_id":"W4-A1-3","kind":"answer","answer":"B","explanation_vi":"¶2 \"a student who presses the wrong button will not notice that the answer is ridiculous\"."},{"step_no":1,"item_id":"W4-A1-4","kind":"answer","answer":"D","explanation_vi":"¶3 \"a tool changes what we need to learn… less important… but more important for checking\"."},{"step_no":1,"item_id":"W4-A1-5","kind":"answer","answer":"B","explanation_vi":null},{"step_no":1,"item_id":"W4-A1-6","kind":"answer","answer":"A","explanation_vi":"¶4 \"the answer will depend less on the tool itself than on the rules and habits…\"."},{"step_no":1,"item_id":"step-1:note","kind":"note","answer":null,"explanation_vi":"Thứ Hai 9/11 · A1 đọc hiểu (264 từ)."},{"step_no":2,"item_id":"W4-A2-1","kind":"answer","answer":"C","explanation_vi":"give up = bỏ cuộc."},{"step_no":2,"item_id":"W4-A2-2","kind":"answer","answer":"B","explanation_vi":"be especially + tính từ."},{"step_no":2,"item_id":"W4-A2-3","kind":"answer","answer":"B","explanation_vi":"sound + tính từ: convincing (nghe có vẻ thuyết phục). ĐÃ SỬA (FIXLIST): bộ phương án cũ confidence/confidently/confide/confident trùng y hệt câu 13 baseline."},{"step_no":2,"item_id":"W4-A2-4","kind":"answer","answer":"A","explanation_vi":"treat… as…"},{"step_no":2,"item_id":"W4-A2-5","kind":"answer","answer":"B","explanation_vi":"supports their learning rather than replacing it."},{"step_no":2,"item_id":"W4-A2-6","kind":"answer","answer":"C","explanation_vi":"has been mostly + tính từ."},{"step_no":2,"item_id":"W4-A2-7","kind":"answer","answer":"A","explanation_vi":"review the guidelines."},{"step_no":2,"item_id":"W4-A2-8","kind":"answer","answer":"B","explanation_vi":"if necessary."},{"step_no":2,"item_id":"step-2:note","kind":"note","answer":null,"explanation_vi":"Thứ Hai 9/11 · A2 điền đoạn văn (181 từ). Dạng từ: 2, 3, 6. Sau đó 5' sổ lỗi."},{"step_no":3,"item_id":"W4-A3-1","kind":"answer","answer":"It is believed that AI will change the way we learn.","explanation_vi":"Cũng chấp nhận: (bỏ that cũng được) · Không chấp nhận: It is believed AI changes… (đổi thì)"},{"step_no":3,"item_id":"W4-A3-2","kind":"answer","answer":"The teacher told us not to copy answers from a chatbot.","explanation_vi":"Cũng chấp nhận: — · Không chấp nhận: …us don't copy…; …us to not copy… (theo chuẩn đề thi)"},{"step_no":3,"item_id":"W4-A3-3","kind":"answer","answer":"If you don't check the facts, you may end up believing false information.","explanation_vi":"Cũng chấp nhận: …do not… · …might / could end up… · Không chấp nhận: If you check the facts, you may… (ngược nghĩa). ĐÃ SỬA (FIXLIST): câu gốc \"learn wrong information\" không tự nhiên."},{"step_no":3,"item_id":"W4-A3-4","kind":"answer","answer":"This app is more useful than my old dictionary.","explanation_vi":"Cũng chấp nhận: …than my old dictionary was · Không chấp nhận: …more usefuller…; …less useful…"},{"step_no":3,"item_id":"W4-A3-5","kind":"answer","answer":"This chatbot was built by a group of students last year.","explanation_vi":"Cũng chấp nhận: …was built last year by a group of students · Không chấp nhận: was build; has been built; bỏ tác nhân"},{"step_no":3,"item_id":"W4-A3-6","kind":"answer","answer":"Asking good questions is important.","explanation_vi":"Cũng chấp nhận: — · Không chấp nhận: …are important; To asking…"},{"step_no":3,"item_id":"W4-A3-7","kind":"answer","answer":"She uses AI to plan her revision, which saves her a lot of time.","explanation_vi":"Cũng chấp nhận: — · Không chấp nhận: which save; which it saves; that saves (sau dấu phẩy)"},{"step_no":3,"item_id":"W4-A3-8","kind":"answer","answer":"I wish I had checked the chatbot's answer.","explanation_vi":"Cũng chấp nhận: I wish I'd checked… · Không chấp nhận: I wish I checked…; I wish I have checked…"},{"step_no":3,"item_id":"step-3:note","kind":"note","answer":null,"explanation_vi":"Thứ Ba 10/11, trong buổi · A3 viết lại câu."},{"step_no":4,"item_id":"W4-B1-1i","kind":"answer","answer":"A","explanation_vi":"Dữ liệu/bằng chứng (D)."},{"step_no":4,"item_id":"W4-B1-1ii","kind":"answer","answer":"B","explanation_vi":"So sánh, hình ảnh."},{"step_no":4,"item_id":"W4-B1-1iii","kind":"answer","answer":"A","explanation_vi":"Dữ liệu/bằng chứng (D)."},{"step_no":4,"item_id":"W4-B1-1iv","kind":"answer","answer":"B","explanation_vi":"Khái quát, không có số đo."},{"step_no":4,"item_id":"W4-B1-1v","kind":"answer","answer":"A","explanation_vi":"Dữ liệu/bằng chứng (D)."},{"step_no":4,"item_id":"W4-B1-1vi","kind":"answer","answer":"B","explanation_vi":"Đánh giá về một chính sách."},{"step_no":4,"item_id":"W4-B1-1vii","kind":"answer","answer":"A","explanation_vi":"Dữ liệu/bằng chứng (D)."},{"step_no":4,"item_id":"W4-B1-1viii","kind":"answer","answer":"B","explanation_vi":"Dự đoán, khái quát."},{"step_no":4,"item_id":"W4-B1-2","kind":"sealed","answer":"Ví dụ: (ii) so sánh, hình ảnh · (iv), (viii) khái quát, dự đoán không có số đo · (vi) đánh giá về chính sách.","explanation_vi":"c2 B-T5-DATAOP. Câu 1-2 là BÀI ÔN LẠI SAU 2 TUẦN (purpose=delayed_check, last_practice_date=2026-10-22). ĐÃ SỬA THỨ TỰ (FIXLIST): làm và nộp câu 1-2 TRƯỚC, rồi mới phát câu 3-4."},{"step_no":4,"item_id":"W4-B1-3","kind":"sealed","answer":"The writer assumes the CHATBOT caused the rise (\"it has changed everything\" ¶1; \"My maths test scores went from 6.5… to 8\" ¶2). Other causes: more study time, an easier mid-term test, extra teaching, more familiarity with the test format.","explanation_vi":"c1-c3 B-T2-ASSUME-R; nói như giả định, không như sự thật."},{"step_no":4,"item_id":"W4-B1-4","kind":"sealed","answer":"It assumes that ALL chatbot use means the machine does the thinking, unlike the uses Source A describes (asking where the mistake is, asking for explanations). Quote ¶3.","explanation_vi":"Căn cứ thứ hai cho B-T2-ASSUME-R."},{"step_no":4,"item_id":"step-4:note","kind":"note","answer":null,"explanation_vi":"Thứ Tư 11/11 · 35'. Câu 1-2 (D/C) là bài ôn lại B-T5-DATAOP sau 20 ngày (mốc 22/10); Nguyên không xem lại bài tuần 1. ĐÃ SỬA THỨ TỰ (FIXLIST): câu giả định cũ số 2 gợi ý đáp án cho phát biểu (iv), nên làm sau. purpose=delayed_check chỉ áp cho dòng CSV B-T5-DATAOP."},{"step_no":5,"item_id":"step-5:note","kind":"note","answer":null,"explanation_vi":"Thứ Năm 12/11 · Chỉ Canvas có câu mẫu (10')."},{"step_no":6,"item_id":"step-6:note","kind":"note","answer":null,"explanation_vi":"Thứ Bảy 14/11 · 45'. Bỏ \"(both sources admit some)\" vì Nguồn A không tự nêu giới hạn nào. Đề thử 40 câu đã dời sang thứ Bảy 21/11 (ngoài app), nên bài viết ở lại thứ Bảy."},{"step_no":7,"item_id":"step-7:note","kind":"note","answer":null,"explanation_vi":"Chủ nhật 15/11 chiều (nhịp thường: bài viết thứ Bảy 14/11, sửa bài Chủ nhật) · cùng learning_family FAM-B-AI-1."},{"step_no":8,"item_id":"step-8:note","kind":"note","answer":null,"explanation_vi":"Chủ nhật 15/11, trong buổi (≈ 12'). Ý chính: \"The teacher worries that letting a chatbot write first drafts stops students learning to write: in her small comparison, chatbot users did worse in an in-class test, though she admits this may not be the cause. So she would allow AI only after students have written their own draft, for checking grammar or explaining words.\""},{"step_no":9,"item_id":"W4-C-1","kind":"sealed","answer":"Written by the company that sells the app, to advertise it · only current app users were asked (unhappy users may have left) · \"40% faster\" gives no method and no comparison group · only one month · \"Teachers love it\" has no evidence · no independent source.","explanation_vi":"c1 B-T5-SOURCE (≥ 2 yếu tố)."},{"step_no":9,"item_id":"W4-C-2","kind":"sealed","answer":"Limitation: any one above. Still useful for: what the app CLAIMS to do, and that some users SAY they feel less stressed — a starting point for finding independent evidence.","explanation_vi":"c2 B-T5-SOURCE. purpose=delayed_check."},{"step_no":9,"item_id":"step-9:note","kind":"note","answer":null,"explanation_vi":"Bài ôn lại B-T5-SOURCE, 10', làm vào thứ Hai 23/11 (tuần 6, sau đề thử 21/11; nằm ngoài khoảng ngày 9-15/11 của chủ đề này). Ghi purpose=delayed_check, last_practice_date=2026-11-08: câu 5 thứ Tư 4/11 và góp ý bài viết tuần 3 đều chạm yếu tố \"phương pháp khảo sát\", nên ngày sớm nhất là 22/11."}]$j$::jsonb) as r
where not exists (
    select 1 from english.inquiry_templates it
    where it.id = 'B-W4-AI-HOMEWORK' and it.version = 1 and it.published_at is not null)
on conflict (template_id, template_version, item_id) do nothing;

update english.inquiry_templates set status = 'published', published_at = now()
where id = 'B-W4-AI-HOMEWORK' and version = 1 and published_at is null;

insert into english.schema_migrations(version) values ('0011') on conflict do nothing;
